         ServerPlayer target = targetId == null ? null : level.getServer().getPlayerList().getPlayer(targetId);
         Vec3 from = king.getEyePosition().add(0.0, -0.2, 0.0);
         Vec3 dir = target != null ? target.getEyePosition().subtract(from) : king.getLookAngle();
         LargeFireball ball = new LargeFireball(EntityTypes.FIREBALL, level);
