      com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.STOP, ParticleTypes.SOUL_FIRE_FLAME, king.position(), Vec3.ZERO, 0.0, 0.0, 0);
