   private static void clearCorruptionFor(ServerLevel level, MindState m) {
      if (m != null && !m.corruption.isEmpty()) {
         for (UUID uid : new ArrayList<>(m.corruption.keySet())) {
            m.corruption.remove(uid);
            m.corruptionUntil.remove(uid);
            corruptionCooldown.remove(uid);
            mindMashTick.remove(uid);
            removeCorruptionBar(uid);
            releaseMindPuppet(level.getServer(), uid);
            ServerPlayer p = level.getServer().getPlayerList().getPlayer(uid);
            if (p != null) {
               p.removeEffect(MobEffects.NAUSEA);
               sendCorruptionFx(p, false);
               actionBar(p, "§aThe corruption releases its grip on your mind.");
            }
         }

         for (UUID uid : new ArrayList<>(testCorruptionStage.keySet())) {
            clearTestCorruption(level.getServer(), uid);
         }
      }
   }

