   private static void teardownMindFx(ServerLevel level, MindState m) {
      if (m != null) {
         MinecraftServer server = level.getServer();

         for (UUID uid : new ArrayList<>(m.clones)) {
            Entity c = findEntity(server, uid);
            if (c != null) {
               c.remove(RemovalReason.DISCARDED);
            }
         }

         m.clones.clear();

         for (UUID uid : new ArrayList<>(m.hands.keySet())) {
            Entity h = findEntity(server, uid);
            if (h != null) {
               h.remove(RemovalReason.DISCARDED);
            }
         }

         m.hands.clear();
         m.handAutoRelease.clear();

         for (UUID victim : new ArrayList<>(m.handBars.keySet())) {
            removeHandBar(m, victim);
         }

         for (UUID victim : new ArrayList<>(m.qteBars.keySet())) {
            removeQteBar(m, victim);
            ServerPlayer v = server.getPlayerList().getPlayer(victim);
            if (v != null) {
               v.connection.send(new ClientboundClearTitlesPacket(true));
            }
         }

         m.qteVictims.clear();
         m.qteActive = false;
         if (m.beamA != null) {
            ServerPlayer a = server.getPlayerList().getPlayer(m.beamA);
            if (a != null) {
               sendLinkFx(a, false);
            }
         }

         if (m.beamB != null) {
            ServerPlayer bb = server.getPlayerList().getPlayer(m.beamB);
            if (bb != null) {
               sendLinkFx(bb, false);
            }
         }

         m.beamA = null;
         m.beamB = null;
         m.beamUntil = 0L;
      }
   }

   private static ServerPlayer nearestOtherPlayerIn(ServerLevel level, ServerPlayer p, double range) {
      ServerPlayer best = null;
      double bd = range * range;

      for (ServerPlayer other : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator() && !pl.getUUID().equals(p.getUUID()))) {
         double d = other.distanceToSqr(p);
         if (d < bd) {
            bd = d;
            best = other;
         }
      }

      return best;
   }

