   public static boolean onFullControlHit(LivingEntity victim, DamageSource source) {
      try {
         if (isMindPuppet(victim) && source.getEntity() instanceof ServerPlayer) {
            for (Entry<UUID, UUID> e : new HashMap<>(mindPuppets).entrySet()) {
               if (e.getValue().equals(victim.getUUID())) {
                  MinecraftServer server = victim.level().getServer();
                  ServerPlayer controller = server.getPlayerList().getPlayer(e.getKey());
                  if (controller != null && staffPossessUntil.containsKey(e.getKey())) {
                     actionBar(controller, "§aA friend shatters the possession - the hold breaks!");
                     releaseStaffPossession(server, e.getKey());
                  } else if (controller != null) {
                     breakCorruption(server, controller, "§aA friend shatters the possession - the hold breaks!");
                  } else if (staffPossessUntil.containsKey(e.getKey())) {
                     releaseStaffPossession(server, e.getKey());
                  } else {
                     releaseMindPuppet(server, e.getKey());
                  }
               }
            }

            return true;
         }

         if (!(victim instanceof ServerPlayer sp && corruptionOf(sp.getUUID()) >= 3 && source.getEntity() instanceof ServerPlayer)) {
            return true;
         }

         breakCorruption(sp.level().getServer(), sp, "§aA friend shakes you free - the hold breaks!");
      } catch (Exception var6) {
      }

      return true;
   }

   private static void breakCorruption(MinecraftServer server, ServerPlayer sp, String message) {
      try {
         boolean cleared = false;

         for (ActiveBoss b : bosses.values()) {
            if (b.mind != null && b.mind.corruption.remove(sp.getUUID()) != null) {
               b.mind.corruptionUntil.remove(sp.getUUID());
               cleared = true;
            }
         }

         if (testCorruptionStage.remove(sp.getUUID()) != null) {
            testCorruptionUntil.remove(sp.getUUID());
            cleared = true;
         }

         if (cleared) {
            sp.removeEffect(MobEffects.NAUSEA);
            removeCorruptionBar(sp.getUUID());
            sendCorruptionFx(sp, false);
            if (message != null) {
               actionBar(sp, message);
            }

            corruptionBreakBurst(sp);
         }

         releaseMindPuppet(server, sp.getUUID());
      } catch (Exception var6) {
      }
   }

