   public static boolean onDevourDamage(LivingEntity victim, DamageSource source, float amount) {
      try {
         if (source.getEntity() instanceof Mob king && isDevouringAttacker(king) && victim instanceof ServerPlayer p && p.isBlocking()) {
            ItemStack raised = p.getUseItem();
            if (!raised.isEmpty() && raised.isDamageableItem() && !raised.has(DataComponents.UNBREAKABLE)) {
               raised.hurtAndBreak(5, p, EquipmentSlot.OFFHAND);
            }
         }

         ActiveBoss b = bosses.get(victim.getUUID());
         if (b == null || !b.king || ServerClock.clock(victim.level()) >= b.devourUntil) {
            return true;
         }

         if (source.getEntity() == null && source.getDirectEntity() == null) {
            return true;
         }

         ServerLevel level = (ServerLevel)victim.level();
         if (b.devourHits >= 3) {
            if (source.getDirectEntity() instanceof ServerPlayer p && p.getAttackStrengthScale(0.5F) >= 0.99F) {
               endDevour(level, (Mob)victim, b, "§aThe King's power is undone by a final blow!");
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.POOF, victim.getX(), victim.getY() + 1.5, victim.getZ(), 40, 2.0, 1.5, 2.0, 0.05);
            }

            return true;
         } else {
            if (source.getDirectEntity() instanceof ServerPlayer p && p.getAttackStrengthScale(0.5F) >= 0.99F) {
               b.devourHits++;
               if (b.devourHits >= 3) {
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, victim.getX(), victim.getY() + 1.0, victim.getZ(), 40, 1.5, 1.5, 1.5, 0.1);
                  level.playSound(null, victim.getX(), victim.getY(), victim.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 0.9F, 1.6F);

                  for (ServerPlayer pl : level.getServer().getPlayerList().getPlayers()) {
                     Chat.raw(pl, "§cThe King's shield shatters! §7One more fully-charged blow will end its power.");
                  }
               } else {
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIT, victim.getX(), victim.getY() + 1.5, victim.getZ(), 20, 1.2, 1.0, 1.2, 0.1);
                  level.playSound(null, victim.getX(), victim.getY(), victim.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 0.6F, 1.8F);
               }
            } else if (source.getEntity() instanceof ServerPlayer p && ServerClock.clock(p.level()) % 40L == 0L) {
               p.sendSystemMessage(Component.literal("§7The King's shield shrugs off your weak swing - charge it fully!"), true);
            }

            return false;
         }
      } catch (Exception ignored) {
         return true;
      }
   }

   public static void tickRevenants(MinecraftServer server) {
      if (!revenants.isEmpty() || !revenantBars.isEmpty() || !spawningRevenant.isEmpty()) {
         if (!spawningRevenant.isEmpty()) {
            for (Entry<UUID, RevenantRise> e : new HashMap<>(spawningRevenant).entrySet()) {
               RevenantRise rise = e.getValue();
               rise.ticks--;
               Mob mob = null;
               ServerLevel mobLevel = null;

               for (ServerLevel l : server.getAllLevels()) {
                  if (l.getEntity(e.getKey()) instanceof Mob m && m.isAlive()) {
                     mob = m;
                     mobLevel = l;
                     break;
                  }
               }

               if (mob == null) {
                  if (rise.ticks < -40) {
                     spawningRevenant.remove(e.getKey());
                  }
               } else if (rise.ticks > 0) {
                  mob.setPos(mob.getX(), rise.targetY - rise.ticks * 0.0625, mob.getZ());
                  com.fortuneandfavors.net.FfVfx.particles(mobLevel, ParticleTypes.CRIMSON_SPORE, mob.getX(), mob.getY() + 0.5, mob.getZ(), 3, 0.3, 0.3, 0.3, 0.02);
                  com.fortuneandfavors.net.FfVfx.particles(mobLevel, ParticleTypes.SOUL_FIRE_FLAME, mob.getX(), mob.getY() + 0.3, mob.getZ(), 1, 0.2, 0.2, 0.2, 0.01);
               } else {
                  mob.setPos(mob.getX(), rise.targetY, mob.getZ());
                  mob.setNoAi(false);
                  mob.setInvulnerable(false);
                  spawningRevenant.remove(e.getKey());
                  com.fortuneandfavors.net.FfVfx.particles(mobLevel, ParticleTypes.CRIMSON_SPORE, mob.getX(), mob.getY() + 1.0, mob.getZ(), 30, 1.5, 1.0, 1.5, 0.08);
                  mobLevel.playSound(null, mob.getX(), mob.getY(), mob.getZ(), ModSounds.BOSS_DEATH, SoundSource.HOSTILE, 0.7F, 0.7F);
               }
            }
         }

         if (server.getTickCount() % 10 == 0) {
            for (UUID id : new HashSet<>(revenants)) {
               boolean alive = false;

               for (ServerLevel l : server.getAllLevels()) {
                  if (l.getEntity(id) instanceof Mob m && m.isAlive()) {
                     alive = true;
                     if (!spawningRevenant.containsKey(id)) {
                        m.setNoAi(false);
                        m.setInvulnerable(false);
                     }

                     targetRevenant(l, m);
                     revenantPassiveVfx(l, m);
                     revenantAttack(l, m);
                     ServerBossEvent bar = revenantBars.get(id);
                     if (bar != null) {
                        bar.setProgress(Math.max(0.0F, Math.min(1.0F, m.getHealth() / m.getMaxHealth())));
                     }
                     break;
                  }
               }

               if (!alive) {
                  revenants.remove(id);
                  removeRevenantBar(id);
                  revenantFights.remove(id);
                  spawningRevenant.remove(id);
                  revenantVictims.entrySet().removeIf(en -> en.getValue().equals(id));
               }
            }
         }
      }
   }

   private static void removeRevenantBar(UUID id) {
      ServerBossEvent bar = revenantBars.remove(id);
      if (bar != null) {
         bar.removeAllPlayers();
         bar.setVisible(false);
      }
   }

   private static void targetRevenant(ServerLevel level, Mob rev) {
      ServerPlayer best = nearestRevenantTarget(level, rev);
      if (best != null) {
         rev.setTarget(best);
      }
   }

   private static ServerPlayer nearestRevenantTarget(ServerLevel level, Mob rev) {
      try {
         CustomData data = (CustomData)rev.get(DataComponents.CUSTOM_DATA);
         if (data == null) {
            return null;
         }

         String targets = data.copyTag().getString("ff_revenant_targets").orElse("");
         if (targets.isEmpty()) {
            return null;
         }

         ServerPlayer best = null;
         double bestDist = 4096.0;

         for (String s : targets.split(",")) {
            if (!s.isEmpty()) {
               try {
                  ServerPlayer p = level.getServer().getPlayerList().getPlayer(UUID.fromString(s));
                  if (p != null && p.isAlive()) {
                     double d = p.distanceToSqr(rev);
                     if (d < bestDist) {
                        bestDist = d;
                        best = p;
                     }
                  }
               } catch (IllegalArgumentException var14) {
               }
            }
         }

         if (best != null) {
            return best;
         }

         ServerPlayer fallback = null;

         for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && pl.distanceToSqr(rev) < 4096.0)) {
            if (fallback == null || p.distanceToSqr(rev) < fallback.distanceToSqr(rev)) {
               fallback = p;
            }
         }

         return fallback;
      } catch (Exception ignored) {
         return null;
      }
   }

   private static void revenantPassiveVfx(ServerLevel level, Mob rev) {
      double a = ServerClock.clock(level) * 0.15 % (Math.PI * 2);
      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIMSON_SPORE, rev.getX() + Math.cos(a) * 0.8, rev.getY() + 0.3, rev.getZ() + Math.sin(a) * 0.8, 1, 0.0, 0.05, 0.0, 0.0);
      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL_FIRE_FLAME, rev.getX(), rev.getY() + 0.2, rev.getZ(), 1, 0.2, 0.1, 0.2, 0.01);
   }

   private static void revenantAttack(ServerLevel level, Mob rev) {
      if (!spawningRevenant.containsKey(rev.getUUID())) {
         ServerPlayer target = nearestRevenantTarget(level, rev);
         if (target != null) {
            RevenantFight f = revenantFights.computeIfAbsent(rev.getUUID(), k -> new RevenantFight());
            long now = ServerClock.clock(level);
            double dist = rev.distanceToSqr(target);
            if (dist < 12.25 && now >= f.nextCleave) {
               f.nextCleave = now + 100L;
               target.hurtServer(level, level.damageSources().mobAttack(rev), 4.0F);
               Vec3 kb = target.position().subtract(rev.position()).normalize().scale(1.1);
               target.setDeltaMovement(target.getDeltaMovement().x + kb.x, 0.45, target.getDeltaMovement().z + kb.z);
               target.hurtMarked = true;
               level.playSound(null, rev.getX(), rev.getY(), rev.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 0.8F, 0.9F);

               for (int i = 0; i < 12; i++) {
                  double a = (now * 0.3 + i * (Math.PI / 6)) % (Math.PI * 2);
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, rev.getX() + Math.cos(a) * 1.6, rev.getY() + 0.9, rev.getZ() + Math.sin(a) * 1.6, 1, 0.0, 0.0, 0.0, 0.02
                  );
               }
            }

            if (dist < 196.0 && now >= f.nextDrain) {
               f.nextDrain = now + 160L;
               Vec3 from = rev.getEyePosition();
               Vec3 to = target.getEyePosition().add(0.0, -0.3, 0.0);
               Vec3 dir = to.subtract(from);

               for (int i = 0; i < 10; i++) {
                  double t = i / 10.0;
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIMSON_SPORE, from.x + dir.x * t, from.y + dir.y * t, from.z + dir.z * t, 1, 0.04, 0.04, 0.04, 0.0);
               }

               target.hurtServer(level, level.damageSources().magic(), 3.0F);
               rev.heal(3.0F);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.HEART, rev.getX(), rev.getY() + 1.5, rev.getZ(), 4, 0.4, 0.4, 0.4, 0.0);
               level.playSound(null, rev.getX(), rev.getY(), rev.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 0.7F, 0.7F);
            }
         }
      }
   }

   public static void onPlayerDeath(ServerLevel level, ServerPlayer victim) {
      // The end of a takeover comes first, for two reasons: the totem the Mindbinder tore out of
      // the pack has to be back in it before the pack is copied, and a body that respawns still
      // wearing somebody else's camera is the softlock this whole path exists to avoid.
      boolean takeoverEnded = endTakeoverOnDeath(victim);
      // Was this death the hold's? Asked before the hold is spent, because spending it is what
      // the question is about - and asked at all because the fallback inside is only safe for a
      // death the Mindbinder caused (see isCorruptionDeath).
      boolean corruptionDeath = isCorruptionDeath(victim, takeoverEnded);
      // Before anything else can look at an empty inventory: a death the
      // Mindbinder caused returns what the player was carrying (see
      // corruptionHoldsDrops).
      restoreCorruptionDeath(victim, corruptionDeath);
      wardenDeathFeast(level, victim);
      if (bodyTakeovers.remove(victim.getUUID()) != null) {
         bodyTakeoverClicks.remove(victim.getUUID());
         spawnSculkInfected(level, victim, victim.getX(), victim.getY(), victim.getZ());
      }

      if (isInSnowRealm(victim)) {
         for (ActiveBoss b : bosses.values()) {
            if (b.snowQueen && b.snow != null) {
               b.snow.realmPlayers.remove(victim.getUUID());
            }
         }

         snowRealmPos.remove(victim.getUUID());
      }

      List<ItemStack> snowDeposit = realmDeposits.remove(victim.getUUID());
      if (snowDeposit != null) {
         placeRealmIceCube(level, victim, snowDeposit);
      }

      if (mindTakenLife.remove(victim.getUUID())) {
         spawnMindEcho(level, victim);
      } else {
         for (Entry<UUID, ActiveBoss> e : bosses.entrySet()) {
            ActiveBoss b = e.getValue();
            if (b.king && b.bloodPhase == 2 && victim.getUUID().equals(b.bloodTarget)) {
               b.bloodPhase = 0;
               b.bloodTarget = null;
               hideBloodBar(b);
               b.nextBlood = ServerClock.clock(level) + 400L;
               b.kingPhase3 = true;
               b.bar.setColor(BossBarColor.WHITE);
               if (level.getEntity(e.getKey()) instanceof Mob kingMob) {
                  kingMob.setNoAi(false);
                  kingMob.setHealth(kingMob.getMaxHealth() * 0.5F);
                  AttributeInstance dmg = kingMob.getAttribute(Attributes.ATTACK_DAMAGE);
                  if (dmg != null) {
                     dmg.setBaseValue(15.0);
                  }

                  level.playSound(null, kingMob.getX(), kingMob.getY(), kingMob.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 1.0F, 0.4F);
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIMSON_SPORE, kingMob.getX(), kingMob.getY() + 1.2, kingMob.getZ(), 60, 2.5, 1.5, 2.5, 0.1);
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.ANGRY_VILLAGER, kingMob.getX(), kingMob.getY() + kingMob.getBbHeight(), kingMob.getZ(), 14, 1.2, 0.5, 1.2, 0.0
                  );
               }

               for (ServerPlayer p : level.getServer().getPlayerList().getPlayers()) {
                  actionBar(
                     p, "§4The King drinks the life of §f" + victim.getName().getString() + "§4 - it recovers and grows enraged. Its loot will be legendary."
                  );
               }

               spawnBloodRevenant(level, victim, b);
               return;
            }
         }
      }
   }

   /**
    * A player who dies with the Mindbinder holding them does not leave a weak
    * echo behind - the Mindbinder keeps the whole of them. What rises is a
    * mind-controlled copy: their skin, their name, their gear and their body, so
    * it walks, falls and swings exactly the way the player it was copied from
    * does.
    *
    * <p>The gear is <b>copied</b> onto the puppet and never removed from the
    * original. That is the whole rule: the dead player still owns every item they
    * owned when they died (what is left of their inventory falls or is kept by
    * Nice Keep Inventory as normal), and the copy merely wears a duplicate.
    */
   private static void spawnMindEcho(ServerLevel level, ServerPlayer victim) {
      try {
         UUID fakeId = UUID.randomUUID();
         GameProfile profile;
         try {
            profile = new GameProfile(fakeId, victim.getName().getString(), new PropertyMap(victim.getGameProfile().properties()));
         } catch (Exception ignored) {
            profile = new GameProfile(fakeId, victim.getName().getString());
         }

         PossessedPlayer copy = new PossessedPlayer(level.getServer(), level, profile);
         copy.setInvulnerable(false);
         copy.getAbilities().invulnerable = false;
         AttributeInstance hp = copy.getAttribute(Attributes.MAX_HEALTH);
         if (hp != null) {
            hp.setBaseValue(40.0);
         }

         copy.setHealth(40.0F);
         copy.setCustomName(Component.literal("§5§lMind-Controlled " + victim.getName().getString()));
         copy.setCustomNameVisible(true);
         copy.setGlowingTag(true);
         // Copies items purely visually onto puppet; victim's inventory is NOT taken or touched
         copy.setItemSlot(EquipmentSlot.HEAD, victim.getItemBySlot(EquipmentSlot.HEAD).copy());
         copy.setItemSlot(EquipmentSlot.CHEST, victim.getItemBySlot(EquipmentSlot.CHEST).copy());
         copy.setItemSlot(EquipmentSlot.LEGS, victim.getItemBySlot(EquipmentSlot.LEGS).copy());
         copy.setItemSlot(EquipmentSlot.FEET, victim.getItemBySlot(EquipmentSlot.FEET).copy());
         copy.setItemSlot(EquipmentSlot.MAINHAND, victim.getMainHandItem().copy());
         copy.setItemSlot(EquipmentSlot.OFFHAND, victim.getOffhandItem().copy());
         BlockPos surface = safeSurfacePos(level, victim);
         copy.setPos(surface.getX() + 0.5, surface.getY(), surface.getZ() + 0.5);

         sendPuppetInfo(level.getServer(), copy);
         level.addFreshEntity(copy);
         mindEchoes.add(copy.getUUID());
         mindEchoSpawnTime.put(copy.getUUID(), ServerClock.clock(level));
         double x = victim.getX();
         double y = victim.getY() + 1.0;
         double z = victim.getZ();
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, x, y, z, 26, 1.0, 1.0, 1.0, 0.05);

         for (int i = 0; i < 18; i++) {
            double a = i / 18.0 * Math.PI * 2.0;
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.1F), x + Math.cos(a) * 1.4, y, z + Math.sin(a) * 1.4, 1, 0.03, 0.2, 0.03, 0.02);
         }

         level.playSound(null, x, y, z, SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 0.9F, 0.35F);
         level.playSound(null, x, y, z, SoundEvents.ENDERMAN_TELEPORT, SoundSource.HOSTILE, 0.7F, 0.5F);
         level.playSound(null, x, y, z, SoundEvents.GENERIC_EXPLODE, SoundSource.HOSTILE, 0.8F, 0.35F);

         for (ServerPlayer p : level.getServer().getPlayerList().getPlayers()) {
            Chat.raw(p, "§5" + victim.getName().getString() + " rises again - the Mindbinder is wearing them now.");
         }

         mindSay(level.getServer(), "§7..." + victim.getName().getString() + "? §7you said you'd come back for me.");
      } catch (Exception var17) {
      }
   }

