   private static void triggerMindbinderHallucination(ServerLevel level, ServerPlayer p, long now) {
      try {
         LivingEntity standIn = null;
         double bd = 324.0;

         for (ServerPlayer pl : level.getPlayers(plx -> plx.isAlive() && !plx.isSpectator() && !plx.getUUID().equals(p.getUUID()))) {
            double d = pl.distanceToSqr(p);
            if (d < bd) {
               bd = d;
               standIn = pl;
            }
         }

         if (standIn == null) {
            for (LivingEntity e : level.getEntitiesOfClass(
               LivingEntity.class, p.getBoundingBox().inflate(18.0), le -> le.isAlive() && le != p && !(le instanceof ArmorStand)
            )) {
               double d = e.distanceToSqr(p);
               if (d < bd) {
                  bd = d;
                  standIn = e;
               }
            }
         }

         double x = standIn != null ? standIn.getX() : p.getX() + (RANDOM.nextDouble() - 0.5) * 8.0;
         double y = standIn != null ? standIn.getY() : p.getY();
         double z = standIn != null ? standIn.getZ() : p.getZ() + (RANDOM.nextDouble() - 0.5) * 8.0;
         Entity realBoss = liveMindbinderEntity(level);
         if (realBoss != null) {
            setEntityInvisibleFor(realBoss, p, true);
            mindHallucHiddenBoss.put(p.getUUID(), realBoss.getUUID());
            mindHallucHiddenUntil.put(p.getUUID(), now + 45L);
         }

         mindHallucActiveUntil.put(p.getUUID(), now + 45L);
         if (RANDOM.nextInt(3) == 0) {
            ServerPlayer friend = randomOnlinePlayer(level);
            if (friend != null) {
               Player fake = spawnFakeFriend(level, friend, x, y, z);
               if (fake != null) {
                  mindHallucinations.put(fake.getUUID(), now + 45L);
                  mindHallucViewer.put(fake.getUUID(), p.getUUID());
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, x, y + 1.0, z, 24, 1.2, 1.2, 1.2, 0.06);
                  com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.3F), x, y + 1.0, z, 14, 0.8, 0.8, 0.8, 0.05);
                  level.playSound(null, x, y, z, SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 0.8F, 0.5F);
                  return;
               }
            }
         }

         Witch vision = (Witch)EntityTypes.WITCH.create(level, EntitySpawnReason.COMMAND);
         if (vision == null) {
            return;
         }

         vision.setNoAi(true);
         vision.setInvulnerable(true);
         vision.setGlowingTag(true);
         vision.setCustomName(Component.literal("§5§lThe Mindbinder"));
         vision.setCustomNameVisible(true);
         vision.setPos(x, y, z);
         level.addFreshEntity(vision);
         mindHallucinations.put(vision.getUUID(), now + 45L);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, x, y + 1.0, z, 24, 1.2, 1.2, 1.2, 0.06);
         com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.3F), x, y + 1.0, z, 14, 0.8, 0.8, 0.8, 0.05);
         level.playSound(null, x, y, z, SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 0.8F, 0.5F);
      } catch (Exception var16) {
      }
   }

   private static Entity liveMindbinderEntity(ServerLevel level) {
      for (Entry<UUID, ActiveBoss> e : bosses.entrySet()) {
         if (e.getValue().mind != null) {
            Entity ent = level.getEntity(e.getKey());
            if (ent != null && ent.isAlive()) {
               return ent;
            }
         }
      }

      return null;
   }

