   private static void setEntityInvisibleFor(Entity target, ServerPlayer viewer, boolean invisible) {
      try {
         if (target == null || viewer == null || viewer.connection == null || SHARED_FLAGS_FIELD == null) {
            return;
         }

         EntityDataAccessor<Byte> acc = (EntityDataAccessor<Byte>)SHARED_FLAGS_FIELD.get(null);
         byte flags = (Byte)target.getEntityData().get(acc);
         byte next = invisible ? (byte)(flags | 32) : (byte)(flags & -33);
         viewer.connection.send(new ClientboundSetEntityDataPacket(target.getId(), List.of(DataValue.create(acc, next))));
      } catch (Exception var6) {
      }
   }

