   public static void tickMindHallucinations(MinecraftServer server) {
      try {
         long now = 0L;

         for (Entry<UUID, UUID> h : new HashMap<>(mindHallucHiddenBoss).entrySet()) {
            ServerPlayer viewer = server.getPlayerList().getPlayer(h.getKey());
            if (viewer != null && viewer.isAlive()) {
               if (viewer.level() instanceof ServerLevel l) {
                  now = ServerClock.clock(l);
                  if (now >= mindHallucHiddenUntil.getOrDefault(h.getKey(), 0L)) {
                     setEntityInvisibleFor(l.getEntity(h.getValue()), viewer, false);
                     mindHallucHiddenBoss.remove(h.getKey());
                     mindHallucHiddenUntil.remove(h.getKey());
                  } else {
                     setEntityInvisibleFor(l.getEntity(h.getValue()), viewer, true);
                  }
               }
            } else {
               mindHallucHiddenBoss.remove(h.getKey());
               mindHallucHiddenUntil.remove(h.getKey());
            }
         }

         for (Entry<UUID, Long> e : new HashMap<>(mindHallucinations).entrySet()) {
            boolean gone = true;

            for (ServerLevel l : server.getAllLevels()) {
               Entity ent = l.getEntity(e.getKey());
               if (ent != null && ent.isAlive()) {
                  gone = false;
                  UUID viewerId = testIllusions.get(e.getKey());
                  if (viewerId == null) {
                     viewerId = mindHallucViewer.get(e.getKey());
                  }

                  if (viewerId != null) {
                     driveTestIllusion(l, ent, viewerId);
                  }

                  if (ServerClock.clock(l) >= e.getValue()) {
                     if (ent instanceof PossessedPlayer) {
                        removePuppetInfo(server, e.getKey());
                     }

                     ent.remove(RemovalReason.DISCARDED);
                     mindHallucinations.remove(e.getKey());
                     testIllusions.remove(e.getKey());
                     mindHallucViewer.remove(e.getKey());
                  }
                  break;
               }
            }

            if (gone) {
               mindHallucinations.remove(e.getKey());
               testIllusions.remove(e.getKey());
               mindHallucViewer.remove(e.getKey());
            }
         }
      } catch (Exception var10) {
      }
   }

   private static void driveTestIllusion(ServerLevel level, Entity ent, UUID casterId) {
      try {
         if (!(ent instanceof Player fake && level.getServer().getPlayerList().getPlayer(casterId) instanceof ServerPlayer caster && caster.isAlive())) {
            return;
         }

         long now = ServerClock.clock(level);
         double dx = caster.getX() - fake.getX();
         double dz = caster.getZ() - fake.getZ();
         double dist = Math.sqrt(dx * dx + dz * dz);
         double mx = 0.0;
         double mz = 0.0;
         if (dist > 0.05) {
            if (dist > 3.2) {
               mx = dx / dist * 0.12;
               mz = dz / dist * 0.12;
            } else if (dist < 1.8) {
               mx = -dx / dist * 0.12;
               mz = -dz / dist * 0.12;
            } else {
               double px = -dz / dist;
               double pz = dx / dist;
               mx = px * Math.sin(now * 0.09) * 0.3;
               mz = pz * Math.sin(now * 0.09) * 0.3;
            }
         }

         float yaw = (float)Math.toDegrees(Math.atan2(-dx, dz));
         fake.setYRot(yaw);
         fake.setYHeadRot(yaw);
         double nx = fake.getX() + mx;
         double nz = fake.getZ() + mz;
         double hop = now % 40L < 10L && dist > 1.0 ? 0.25 : 0.0;
         double ny = fake.getY() + hop;

         for (int i = 0; i < 8 && !puppetSolidAt(level, nx, ny - 1.0, nz); i++) {
            ny -= 0.5;
         }

         fake.setPos(nx, Math.max(level.getMinY() + 1, ny), nz);
      } catch (Exception var27) {
      }
   }

   public static void tickMindEchoes(MinecraftServer server) {
      try {
         for (UUID id : new HashSet<>(mindEchoes)) {
            if (!(findEntity(server, id) instanceof LivingEntity echo) || !echo.isAlive()) {
               // The copy is gone - take its name off the tab list too, or a dead
               // puppet stays listed forever.
               removePuppetInfo(server, id);
               mindEchoes.remove(id);
               mindEchoSpawnTime.remove(id);
               continue;
            }

            ServerLevel level = (ServerLevel)echo.level();
            long now = ServerClock.clock(level);

            // Despawn after 60 seconds (1200 ticks) so it does not stay forever
            long spawnAt = mindEchoSpawnTime.getOrDefault(id, now);
            if (now - spawnAt > 1200L) {
               echo.discard();
               removePuppetInfo(server, id);
               mindEchoes.remove(id);
               mindEchoSpawnTime.remove(id);
               continue;
            }

            if (echo instanceof PossessedPlayer copy) {
               // Ensure vulnerability and no godmode
               copy.setInvulnerable(false);
               copy.getAbilities().invulnerable = false;
               // A mind-controlled copy hunts with active AI. It tracks the nearest player.
               ServerPlayer prey = nearestPrey(level, copy);
               if (prey != null) {
                  // The puppet is a fake player rather than a mob, so there is no look controller to
                  // drive: it is aimed by hand, at the same rates a look controller would use.
                  double lx = prey.getX() - copy.getX();
                  double lz = prey.getZ() - copy.getZ();
                  double ly = prey.getEyeY() - copy.getEyeY();
                  float yaw = (float)(net.minecraft.util.Mth.atan2(lz, lx) * (180.0F / (float)Math.PI)) - 90.0F;
                  float pitch = (float)(-(net.minecraft.util.Mth.atan2(ly, Math.sqrt(lx * lx + lz * lz)) * (180.0F / (float)Math.PI)));
                  copy.setYRot(yaw);
                  copy.setXRot(pitch);
                  copy.setYHeadRot(yaw);
                  Vec3 dir = prey.position().subtract(copy.position());
                  if (dir.horizontalDistanceSqr() > 1.5) {
                     Vec3 step = new Vec3(dir.x, 0.0, dir.z).normalize().scale(0.35);
                     copy.setDeltaMovement(step.x, copy.getDeltaMovement().y, step.z);
                     copy.hurtMarked = true;
                  }
                  if (now % 20L == 0L && copy.distanceToSqr(prey) < 9.0) {
                     com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SWEEP_ATTACK, prey.getX(), prey.getY() + 0.6, prey.getZ(), 10, 0.4, 0.4, 0.4, 0.05);
                     level.playSound(null, prey.blockPosition(), SoundEvents.PLAYER_ATTACK_SWEEP, SoundSource.HOSTILE, 0.9F, 1.0F);
                     prey.hurtServer(level, level.damageSources().mobAttack(copy), 6.0F);
                  }
               }
               if (now % 10L == 0L) {
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, copy.getX(), copy.getY() + 1.0, copy.getZ(), 8, 0.8, 0.9, 0.8, 0.03);
                  com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.0F), copy.getX(), copy.getY() + 0.6, copy.getZ(), 4, 0.7, 0.4, 0.7, 0.02);
               }
               continue;
            }

            if (now % 20L == 0L) {
               for (LivingEntity near : level.getEntitiesOfClass(LivingEntity.class, echo.getBoundingBox().inflate(2.2), le -> le.isAlive() && le != echo)) {
                  near.hurtServer(level, level.damageSources().magic(), 2.0F);
               }
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, echo.getX(), echo.getY() + 0.6, echo.getZ(), 12, 1.6, 0.4, 1.6, 0.03);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.0F), echo.getX(), echo.getY() + 0.4, echo.getZ(), 6, 1.4, 0.2, 1.4, 0.02);
            }
         }
      } catch (Exception var10) {
      }
   }

   /** The closest living player to a mind-controlled copy. */
   private static ServerPlayer nearestPrey(ServerLevel level, LivingEntity copy) {
      ServerPlayer best = null;
      double bd = 48.0 * 48.0;
      for (ServerPlayer p : level.getPlayers(pl -> pl != null && pl.isAlive() && !pl.isSpectator())) {
         double d = p.distanceToSqr(copy);
         if (d < bd) {
            bd = d;
            best = p;
         }
      }
      return best;
   }

