   private static void startMindQte(MinecraftServer server, ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      List<ServerPlayer> targets = new ArrayList<>();

      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator())) {
         if (p.distanceToSqr(witch) < 2304.0) {
            targets.add(p);
         }
      }

      if (!targets.isEmpty()) {
         int pick = Math.min(m.phase2 ? 2 : 1, targets.size());
         m.qteVictims.clear();

         for (int i = 0; i < pick; i++) {
            int idx = RANDOM.nextInt(targets.size());
            m.qteVictims.add(targets.get(idx).getUUID());
            targets.remove(idx);
         }

         m.qteActive = true;
         m.qteUntil = now + (m.phase2 ? 20 : 30);
         m.nextQte = now + (m.phase2 ? 200 : 340);
         witch.setNoAi(true);
         mindCastFx(level, witch);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, witch.getX(), witch.getY() + 1.8, witch.getZ(), 20, 0.5, 0.6, 0.5, 0.03);
         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 1.0F, 0.5F);

         for (UUID uid : m.qteVictims) {
            ServerPlayer v = server.getPlayerList().getPlayer(uid);
            if (v != null) {
               ServerBossEvent qteBar = new ServerBossEvent(
                  UUID.randomUUID(), Component.literal("§5§lSNEAK §f- break the Mindbinder's hold!"), BossBarColor.PURPLE, BossBarOverlay.NOTCHED_10
               );
               qteBar.setVisible(true);
               qteBar.addPlayer(v);
               qteBar.setProgress(1.0F);
               m.qteBars.put(uid, qteBar);
               v.connection.send(new ClientboundSetTitleTextPacket(Component.literal("")));
               v.connection.send(new ClientboundSetTitlesAnimationPacket(2, 120, 5));
               v.connection.send(new ClientboundSetSubtitleTextPacket(Component.literal("§5§lSNEAK NOW! §7- §fbreak the Mindbinder's hold")));
            }
         }
      }
   }

   /** How long one stage holds before it fades to the one below it. */
   private static int corruptionStageTicks(MindState m) {
      return m.phase2 ? 560 : 440;
   }

   private static void corrupt(ActiveBoss b, ServerLevel level, ServerPlayer victim) {
      MindState m = b.mind;
      if (maskSurgeImmune.getOrDefault(victim.getUUID(), 0L) > ServerClock.clock(level)) {
         actionBar(victim, "§bYour surge holds - §7the Mindbinder cannot take you.");
      } else {
         int cur = m.corruption.getOrDefault(victim.getUUID(), 0);
         if (cur < 3) {
            if (corruptionCooldown.getOrDefault(victim.getUUID(), 0L) <= ServerClock.clock(level)) {
               int next = cur + 1;
               m.corruption.put(victim.getUUID(), next);
               corruptionCooldown.put(victim.getUUID(), ServerClock.clock(level) + 200L);
               m.corruptionUntil.put(victim.getUUID(), ServerClock.clock(level) + corruptionStageTicks(m));
               // The hold takes: a violet thread from him to the mind, a crack over it, static in the eyes.
               Entity binder = liveMindbinderEntity(level);
               if (binder != null) {
                  com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.BEAM, ParticleTypes.PORTAL, binder.position().add(0.0, 1.6, 0.0), victim.getEyePosition(), 0.0, 0.0, next >= 3 ? 0xFF4CB0 : MIND_VIOLET);
               }
               com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.NOVA, ParticleTypes.PORTAL, victim.position(), Vec3.ZERO, 1.5 + next, 0.0, MIND_VIOLET);
               com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.TEAR, ParticleTypes.PORTAL, victim.position().add(0.0, 2.6, 0.0), new Vec3(1.0, 0.0, 0.0), 0.5 + 0.3 * next, 20, MIND_VIOLET);
               com.fortuneandfavors.net.FfNet.send(victim, new com.fortuneandfavors.net.FfScreenFxPayload(com.fortuneandfavors.net.FfScreenFxPayload.FX_FRACTURE, true));
               level.playSound(null, victim.getX(), victim.getY(), victim.getZ(), SoundEvents.ELDER_GUARDIAN_CURSE, SoundSource.HOSTILE, 0.6F, 1.4F + 0.2F * next);
               actionBar(victim, switch (next) {
                  case 1 -> "§5\u2726 CORRUPTION I §7- something whispers in your head";
                  case 2 -> "§5\u2726 CORRUPTION II §7- your hands are not quite yours";
                  default -> "§c\u2726 CORRUPTION III §7- it has you. §fmash JUMP";
               });
               com.fortuneandfavors.net.FfVfx.enter();
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, victim.getX(), victim.getY() + 1.0, victim.getZ(), 25, 0.5, 0.6, 0.5, 0.04);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.2F), victim.getX(), victim.getY() + 1.0, victim.getZ(), 12, 0.5, 0.6, 0.5, 0.05);
               com.fortuneandfavors.net.FfVfx.exit();
            }
         }
      }
   }

