   public static void spawnMindPuppet(ServerPlayer p) {
      try {
         if (p == null || !(p.level() instanceof ServerLevel level && !mindPuppets.containsKey(p.getUUID()))) {
            return;
         }

         MinecraftServer server = level.getServer();
         UUID fakeId = UUID.randomUUID();

         GameProfile profile;
         try {
            profile = new GameProfile(fakeId, p.getName().getString(), new PropertyMap(p.getGameProfile().properties()));
         } catch (Exception ignored) {
            profile = new GameProfile(fakeId, p.getName().getString());
         }

         PossessedPlayer puppet = new PossessedPlayer(server, level, profile);
         puppet.setPos(p.getX(), p.getY(), p.getZ());
         puppet.setYRot(p.getYRot());
         puppet.setXRot(p.getXRot());
         AttributeInstance maxHp = puppet.getAttribute(Attributes.MAX_HEALTH);
         if (maxHp != null) {
            maxHp.setBaseValue(40.0);
         }

         puppet.setHealth(40.0F);
         puppet.setCustomName(Component.literal("§5§l" + p.getName().getString()));
         puppet.setCustomNameVisible(true);
         puppet.setItemSlot(EquipmentSlot.HEAD, p.getItemBySlot(EquipmentSlot.HEAD).copy());
         puppet.setItemSlot(EquipmentSlot.CHEST, p.getItemBySlot(EquipmentSlot.CHEST).copy());
         puppet.setItemSlot(EquipmentSlot.LEGS, p.getItemBySlot(EquipmentSlot.LEGS).copy());
         puppet.setItemSlot(EquipmentSlot.FEET, p.getItemBySlot(EquipmentSlot.FEET).copy());
         puppet.setItemSlot(EquipmentSlot.MAINHAND, p.getMainHandItem().copy());
         puppet.setItemSlot(EquipmentSlot.OFFHAND, p.getOffhandItem().copy());
         puppet.setGlowingTag(true);
         puppet.setInvulnerable(false);
         sendPuppetInfo(server, puppet);
         level.addFreshEntity(puppet);
         mindPuppets.put(p.getUUID(), puppet.getUUID());
         mindStruggleMeter.put(p.getUUID(), 480L);
         // Written on the player, so a restart can tell that this body is not its own.
         p.addTag(MIND_HELD_TAG);
         List<ItemStack> taken = new ArrayList<>();

         for (int i = 0; i < p.getInventory().getContainerSize(); i++) {
            ItemStack s = p.getInventory().getItem(i);
            if (s.is(Items.TOTEM_OF_UNDYING)) {
               taken.add(s.copy());
               p.getInventory().setItem(i, ItemStack.EMPTY);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, p.getX(), p.getY() + 1.0, p.getZ(), 14, 0.5, 0.6, 0.5, 0.04);
               actionBar(p, "§cThe Mindbinder tears the totem from your pack!");
               mindSay(server, "§5§lThe Mindbinder§5: '" + p.getName().getString() + ". A totem? No. You don't get to leave early.'");
               break;
            }
         }

         if (!taken.isEmpty()) {
            mindTakenItems.put(p.getUUID(), taken);
         }

         // The mode to give back: the first one recorded, and never spectator - a second takeover
         // landing on a player still in spectator used to record SPECTATOR as their "real" mode, and
         // the release then left them frozen and invulnerable for good.
         if (p.gameMode() != GameType.SPECTATOR) {
            mindPuppetGameType.putIfAbsent(p.getUUID(), p.gameMode());
         }
         p.setGameMode(GameType.SPECTATOR);

         try {
            p.setCamera(puppet);
         } catch (Exception var10) {
         }

         p.setDeltaMovement(0.0, 0.0, 0.0);
         p.hurtMarked = true;
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, p.getX(), p.getY() + 1.0, p.getZ(), 40, 1.0, 1.0, 1.0, 0.06);
         com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.4F), p.getX(), p.getY() + 1.0, p.getZ(), 20, 0.7, 0.8, 0.7, 0.05);
      } catch (Exception var12) {
      }
   }

   // ------------------------------------------------------- reusable puppets

   /**
    * A puppet wearing somebody's face.
    *
    * <p>The mind-controlled copy the Mindbinder makes is a takeover - the player's
    * own body, their camera, their slots. This is the other half of that idea and
    * the one {@code PuppeteerManager} needs: a body that looks like a given player
    * (their profile, so their skin renders), carries a copy of their gear, belongs
    * to nobody, and can be driven from a script. Nothing on the source player is
    * read destructively and nothing on them is changed.
    *
    * @param health what the copy has instead of the player's own hearts - always a
    *               reduced, fixed number, because a puppet is not a second life
    */
   public static ServerPlayer spawnPuppetCopy(ServerLevel level, ServerPlayer source, String displayName, double health, boolean glowing) {
      try {
         if (level == null || source == null) {
            return null;
         }
         UUID fakeId = UUID.randomUUID();
         GameProfile profile;
         try {
            profile = new GameProfile(fakeId, source.getName().getString(), new PropertyMap(source.getGameProfile().properties()));
         } catch (Exception ignored) {
            profile = new GameProfile(fakeId, source.getName().getString());
         }

         PossessedPlayer puppet = new PossessedPlayer(level.getServer(), level, profile);
         puppet.setPos(source.getX(), source.getY(), source.getZ());
         puppet.setYRot(source.getYRot());
         puppet.setXRot(source.getXRot());
         puppet.setInvulnerable(false);
         puppet.getAbilities().invulnerable = false;
         puppet.getAbilities().flying = false;
         AttributeInstance maxHp = puppet.getAttribute(Attributes.MAX_HEALTH);
         if (maxHp != null) {
            maxHp.setBaseValue(Math.max(1.0, health));
         }
         puppet.setHealth((float)Math.max(1.0, health));
         puppet.setGlowingTag(glowing);
         if (displayName != null) {
            puppet.setCustomName(Component.literal(displayName));
            puppet.setCustomNameVisible(true);
         }
         for (EquipmentSlot slot : new EquipmentSlot[]{EquipmentSlot.HEAD, EquipmentSlot.CHEST, EquipmentSlot.LEGS, EquipmentSlot.FEET, EquipmentSlot.MAINHAND, EquipmentSlot.OFFHAND}) {
            puppet.setItemSlot(slot, source.getItemBySlot(slot).copy());
         }
         sendPuppetInfo(level.getServer(), puppet);
         level.addFreshEntity(puppet);
         return puppet;
      } catch (Throwable t) {
         FortuneFavorsMod.LOGGER.warn("Fortune & Favors: could not raise a puppet copy", t);
         return null;
      }
   }

   /**
    * Takes a fake player off the stage cleanly.
    *
    * <p>A fake player is two things as far as every real client is concerned: a
    * tab-list entry and a body. Discarding the body alone leaves a head floating in
    * the player list forever, so both go - and both are dropped even if the client
    * has already left.
    */
   public static void removeFakePlayer(MinecraftServer server, Entity fake) {
      if (fake == null) {
         return;
      }
      try {
         if (fake.level() instanceof ServerLevel level) {
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.POOF, fake.getX(), fake.getY() + 1.0, fake.getZ(), 18, 0.4, 0.6, 0.4, 0.05);
         }
      } catch (Throwable ignored) {
      }
      try {
         if (server != null) {
            removePuppetInfo(server, fake.getUUID());
         }
      } catch (Throwable ignored) {
      }
      try {
         fake.remove(RemovalReason.DISCARDED);
      } catch (Throwable ignored) {
      }
   }

   /** Resends the tab-list entry for a fake player to one viewer (a late joiner). */
   public static void sendFakePlayerTo(ServerPlayer viewer, Entity fake) {
      if (viewer == null || !(fake instanceof PossessedPlayer puppet)) {
         return;
      }
      try {
         viewer.connection.send(puppetInfoPacket(puppet));
      } catch (Throwable ignored) {
      }
   }

   /** True for the mod's fake-player puppets - the ones no player is behind. */
   public static boolean isFakePlayer(Entity entity) {
      return entity instanceof PossessedPlayer;
   }

   /**
    * Every puppet body this mod has made, and when - the sweep's ledger.
    *
    * <p>Keyed by the body's own UUID and written in the constructor, so there is exactly one place
    * that can forget to register a puppet, and it is the place that creates one. The value is the
    * world tick it was born on, which is all the sweep below needs to tell a body somebody is still
    * driving from one that has been left standing in a field since yesterday.
    */
   private static final Map<UUID, Long> puppetBornAt = new HashMap<>();

   /**
    * How long a puppet nobody is driving may exist before the server takes it away.
    *
    * <p>Ninety seconds, and deliberately longer than any scripted copy in the mod: the Illusioner's
    * decoys last seconds, {@code PuppeteerManager}'s puppets are driven and removed by their own
    * code, and every mind-held body is released by the hold that owns it. What reaches this cap is
    * the body nobody owns any more - a puppet whose hold ended badly, a copy whose manager was
    * unloaded by a restart, a body whose controller logged out mid-fight. "Invincible, no AI, does
    * not despawn, still picking things up" is what one of those looks like from the ground, and no
    * amount of fixing the holds one at a time closes it: this closes it for all of them at once.
    */
   private static final long PUPPET_IDLE_TICKS = 1800L;

   /**
    * Takes away any puppet body that nobody is driving - the mod's last line of defence against a
    * copy that outlives its purpose.
    *
    * <p>Called once a tick. It does nothing at all on a server with no puppets, on the same terms
    * the vanish tick does: an empty ledger returns immediately.
    */
   public static void tickPuppetSweep(MinecraftServer server) {
      try {
         if (server == null || puppetBornAt.isEmpty()) {
            return;
         }
         Set<UUID> driven = new HashSet<>(mindPuppets.values());
         driven.addAll(mindEchoes);
         for (Entry<UUID, Long> e : new HashMap<>(puppetBornAt).entrySet()) {
            Entity body = findEntity(server, e.getKey());
            if (!(body instanceof ServerPlayer puppet) || !puppet.isAlive()) {
               // Already gone - the entry is the only thing left of it.
               puppetBornAt.remove(e.getKey());
               removePuppetInfo(server, e.getKey());
               continue;
            }
            long now = ServerClock.clock(body.level());
            if (now < e.getValue()) {
               // The world clock went backwards, which means a reload. Re-date the body rather
               // than mistaking every puppet on the server for an abandoned one.
               puppetBornAt.put(e.getKey(), now);
               continue;
            }
            if (driven.contains(e.getKey()) || now - e.getValue() <= PUPPET_IDLE_TICKS) {
               continue;
            }
            purgePuppet(server, puppet);
         }
      } catch (VirtualMachineError e) {
         throw e;
      } catch (Throwable t) {
         com.fortuneandfavors.FortuneFavorsMod.LOGGER.error("Fortune & Favors: puppet sweep failed", t);
      }
   }

   /**
    * Removes one puppet body in the only way that leaves nothing behind: the costume comes off
    * first.
    *
    * <p>The order matters. A body removed with its inventory intact is a body whose contents go
    * with it - no loot, no steal - and a body removed with the camera of a live player pointed at
    * it is how a staff member ends up watching an empty patch of grass, so an owner is released
    * first if there is one. Nothing here can duplicate an item or destroy one that belonged to a
    * player, because a puppet only ever carried copies.
    */
   public static void purgePuppet(MinecraftServer server, ServerPlayer puppet) {
      try {
         UUID id = puppet.getUUID();
         for (Entry<UUID, UUID> e : new HashMap<>(mindPuppets).entrySet()) {
            if (e.getValue().equals(id)) {
               releaseMindPuppet(server, e.getKey());
               return;
            }
         }
         if (puppet.level() instanceof ServerLevel level) {
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, puppet.getX(), puppet.getY() + 1.0, puppet.getZ(), 20, 0.6, 0.6, 0.6, 0.05);
         }
         puppet.getInventory().clearContent();
         puppetBornAt.remove(id);
         removePuppetInfo(server, id);
         puppet.remove(Entity.RemovalReason.DISCARDED);
      } catch (Throwable t) {
         com.fortuneandfavors.FortuneFavorsMod.LOGGER.error("Fortune & Favors: could not retire a puppet body", t);
      }
   }

