   private static void summonSnowServants(ServerLevel level, Mob queen, ActiveBoss b) {
      int count = b.snow.phase2 ? 3 : 2;

      for (int i = 0; i < count; i++) {
         Mob servant = (Mob)EntityTypes.STRAY.create(level, EntitySpawnReason.COMMAND);
         if (servant != null) {
            AttributeInstance hp = servant.getAttribute(Attributes.MAX_HEALTH);
            if (hp != null) {
               hp.setBaseValue(30.0);
            }

            servant.setHealth(30.0F);
            AttributeInstance dmg = servant.getAttribute(Attributes.ATTACK_DAMAGE);
            if (dmg != null) {
               dmg.setBaseValue(5.0);
            }

            AttributeInstance spd = servant.getAttribute(Attributes.MOVEMENT_SPEED);
            if (spd != null) {
               spd.setBaseValue(0.28);
            }

            servant.setPersistenceRequired();
            servant.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 999999, 0, false, false));
            servant.setRemainingFireTicks(0);
            servant.setCustomName(Component.literal("§bFrozen Servant"));
            servant.setCustomNameVisible(true);
            double a = RANDOM.nextDouble() * Math.PI * 2.0;
            double r = 3.0 + RANDOM.nextDouble() * 4.0;
            double sx = queen.getX() + Math.cos(a) * r;
            double sz = queen.getZ() + Math.sin(a) * r;
            double sy = groundBelow(level, sx, sz, (int)queen.getY());
            servant.setPos(sx, sy, sz);
            CustomData cd = (CustomData)servant.get(DataComponents.CUSTOM_DATA);
            CompoundTag tag = cd != null ? cd.copyTag() : new CompoundTag();
            tag.putString("ff_snow_servant", "1");
            servant.setComponent(DataComponents.CUSTOM_DATA, CustomData.of(tag));
            level.addFreshEntity(servant);
            b.snow.servants.add(servant.getUUID());
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SNOWFLAKE, sx, sy + 1.0, sz, 18, 0.5, 0.7, 0.5, 0.05);
            level.playSound(null, sx, sy, sz, SoundEvents.GLASS_PLACE, SoundSource.HOSTILE, 0.9F, 0.7F);
            com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.ICE_ERUPT, ParticleTypes.SNOWFLAKE, new Vec3(sx, sy, sz), Vec3.ZERO, 2.4, 0.0, 0xBFEFFF);
         }
      }

      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && pl.distanceToSqr(queen) < 1600.0)) {
         // Silenced telegraph announcement
      }
   }

