   private static double groundBelow(ServerLevel level, double x, double z, int startY) {
      for (int dy = 0; dy < 40; dy++) {
         int y = startY - dy;
         if (y < level.getMinY()) {
            return startY;
         }

         BlockPos pos = new BlockPos(Mth.floor(x), y, Mth.floor(z));
         if (!level.getBlockState(pos).isAir() && !level.getBlockState(pos).is(Blocks.SNOW_BLOCK) && !level.getBlockState(pos).is(Blocks.SNOW)) {
            return y + 1.0;
         }
      }

      return startY;
   }

   private static void addSnowFreeze(ServerLevel level, LivingEntity target, int amount, LivingEntity source) {
      if (target != null && target.isAlive() && !bosses.containsKey(target.getUUID())) {
         if (!(target instanceof ServerPlayer p && (p.getAbilities().instabuild || snowThawUntil.containsKey(p.getUUID())))) {
            int cur = Math.min(100, snowFreeze.getOrDefault(target.getUUID(), 0) + amount);
            snowFreeze.put(target.getUUID(), cur);
            target.setTicksFrozen(Math.min(target.getTicksRequiredToFreeze() + 300, target.getTicksFrozen() + amount * 2));
            if (target instanceof ServerPlayer p) {
               actionBar(p, "§b\u2744 Freezing §f" + cur + "%§b - §fget away from the cold!");
               if (cur >= 100) {
                  sealInIce(level, p, source);
               }
            } else if (cur >= 100) {
               freezeMob(level, target);
            }
         }
      }
   }

   public static int snowFreezeAmount(Entity target) {
      return target == null ? 0 : snowFreeze.getOrDefault(target.getUUID(), 0);
   }

   public static void freezeBuildup(ServerLevel level, LivingEntity target, int amount) {
      addSnowFreeze(level, target, amount, null);
   }

   public static boolean isSealed(UUID uuid) {
      return snowThawUntil.containsKey(uuid);
   }

   private static void sealInIce(ServerLevel level, ServerPlayer p, LivingEntity source) {
      snowFreeze.remove(p.getUUID());
      snowThawUntil.put(p.getUUID(), ServerClock.clock(level) + 260L);
      int bx = Mth.floor(p.getX());
      int by = Mth.floor(p.getY());
      int bz = Mth.floor(p.getZ());
      List<BlockPos> blocks = new ArrayList<>();

      for (int dy = 0; dy <= 1; dy++) {
         for (int dx = -1; dx <= 1; dx++) {
            for (int dz = -1; dz <= 1; dz++) {
               if (dx != 0 || dz != 0) {
                  BlockPos pos = new BlockPos(bx + dx, by + dy, bz + dz);
                  if (level.getBlockState(pos).isAir()) {
                     level.setBlock(pos, Blocks.ICE.defaultBlockState(), 3);
                     blocks.add(pos);
                  }
               }
            }
         }
      }

      BlockPos top = new BlockPos(bx, by + 2, bz);
      if (level.getBlockState(top).isAir()) {
         level.setBlock(top, Blocks.ICE.defaultBlockState(), 3);
         blocks.add(top);
      }

      iceCubes.put(p.getUUID(), blocks);
      p.setTicksFrozen(p.getTicksRequiredToFreeze());
      p.setDeltaMovement(0.0, 0.0, 0.0);
      p.hurtMarked = true;
      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SNOWFLAKE, p.getX(), p.getY() + 1.0, p.getZ(), 40, 0.8, 1.0, 0.8, 0.08);
      level.playSound(null, p.getX(), p.getY(), p.getZ(), SoundEvents.GLASS_PLACE, SoundSource.HOSTILE, 1.1F, 0.5F);
      Chat.raw(p, "§b\u2744 You freeze solid! §7A friend can mine you out, wait it out, or mash your attack to shatter the ice.");
      if (source != null) {
         level.playSound(null, p.getX(), p.getY(), p.getZ(), SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 0.9F, 1.6F);
      }
   }

   private static void freezeMob(ServerLevel level, LivingEntity target) {
      snowFreeze.remove(target.getUUID());
      snowMobThawUntil.put(target.getUUID(), ServerClock.clock(level) + 200L);
      target.setTicksFrozen(target.getTicksRequiredToFreeze() + 200);
      target.setDeltaMovement(0.0, 0.0, 0.0);
      target.hurtMarked = true;
      if (target instanceof Mob mob) {
         mob.setNoAi(true);
         mob.setTarget(null);
      }

      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SNOWFLAKE, target.getX(), target.getY() + 1.0, target.getZ(), 26, 0.6, 0.7, 0.6, 0.06);
      com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-1509121, 1.1F), target.getX(), target.getY() + 1.0, target.getZ(), 12, 0.5, 0.6, 0.5, 0.03);
      level.playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.GLASS_PLACE, SoundSource.HOSTILE, 0.9F, 0.7F);
   }

   private static void maybeSnowballLoot(ServerLevel level, LivingEntity killed) {
      if (!(killed instanceof ServerPlayer) && RANDOM.nextInt(100) < 8) {
         int n = 1 + RANDOM.nextInt(3);
         level.addFreshEntity(new ItemEntity(level, killed.getX(), killed.getY() + 0.5, killed.getZ(), new ItemStack(Items.SNOWBALL, n)));
      }
   }

   private static void thawPlayer(ServerLevel level, UUID uuid) {
      List<BlockPos> blocks = iceCubes.remove(uuid);
      snowThawUntil.remove(uuid);
      snowFreeze.remove(uuid);
      snowStruggle.remove(uuid);
      if (blocks != null && level != null && level.getServer() != null) {
         ServerLevel home = level;

         for (ServerLevel l : level.getServer().getAllLevels()) {
            boolean any = false;

            for (BlockPos pos : blocks) {
               if (l.getBlockState(pos).is(Blocks.ICE)) {
                  any = true;
                  break;
               }
            }

            if (any) {
               home = l;
               break;
            }
         }

         double cx = 0.0;
         double cy = 0.0;
         double cz = 0.0;

         for (BlockPos pos : blocks) {
            cx += pos.getX() + 0.5;
            cy += pos.getY() + 0.5;
            cz += pos.getZ() + 0.5;
         }

         int n = Math.max(1, blocks.size());
         cx /= n;
         cy /= n;
         cz /= n;
         com.fortuneandfavors.net.FfVfx.particles(home, ParticleTypes.EGG_CRACK, cx, cy, cz, 22, 1.2, 1.2, 1.2, 0.1);
         com.fortuneandfavors.net.FfVfx.particles(home, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.ICE.defaultBlockState()), cx, cy, cz, 20, 1.1, 1.1, 1.1, 0.14);
         home.playSound(null, cx, cy, cz, SoundEvents.GLASS_BREAK, SoundSource.PLAYERS, 1.0F, 1.15F);

         for (BlockPos pos : blocks) {
            if (home.getBlockState(pos).is(Blocks.ICE)) {
               home.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
               com.fortuneandfavors.net.FfVfx.particles(home, ParticleTypes.SNOWFLAKE, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 6, 0.3, 0.3, 0.3, 0.02);
            }
         }
      }

      ServerPlayer p = level != null && level.getServer() != null ? level.getServer().getPlayerList().getPlayer(uuid) : null;
      if (p != null) {
         p.setTicksFrozen(0);
         actionBar(p, "§b\u2744 The ice cracks - you're free!");
      }
   }

   public static boolean isPrisonBlock(BlockPos pos) {
      return prisonOwnerOf(pos) != null;
   }

   public static UUID prisonOwnerOf(BlockPos pos) {
      for (Entry<UUID, List<BlockPos>> e : iceCubes.entrySet()) {
         if (e.getValue().contains(pos)) {
            return e.getKey();
         }
      }

      return null;
   }

   public static void onPrisonSwing(ServerLevel level, ServerPlayer p) {
      try {
         if (!snowThawUntil.containsKey(p.getUUID())) {
            return;
         }

         int swings = snowStruggle.getOrDefault(p.getUUID(), 0) + 1;
         snowStruggle.put(p.getUUID(), swings);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SNOWFLAKE, p.getX(), p.getY() + 1.0, p.getZ(), 6, 0.4, 0.5, 0.4, 0.05);
         if (swings >= 12) {
            snowStruggle.remove(p.getUUID());
            thawPlayer(level, p.getUUID());
            Chat.raw(p, "§b\u2744 You shatter the ice with your bare hands!");
         } else if (swings % 4 == 0) {
            actionBar(p, "§b\u2744 The ice cracks - §f" + (12 - swings) + " more swings!");
         }
      } catch (Exception var3) {
      }
   }

   public static void onPrisonBlockMined(ServerLevel level, BlockPos pos) {
      for (Entry<UUID, List<BlockPos>> e : new HashMap<>(iceCubes).entrySet()) {
         if (e.getValue().contains(pos)) {
            thawPlayer(level, e.getKey());
            return;
         }
      }
   }

   public static boolean isIceCubeDeposit(BlockPos pos) {
      for (BlockPos key : iceCubeDeposits.keySet()) {
         if (Math.abs(key.getX() - pos.getX()) <= 1 && Math.abs(key.getY() - pos.getY()) <= 1 && Math.abs(key.getZ() - pos.getZ()) <= 1) {
            return true;
         }
      }

      return false;
   }

   public static void onIceCubeDepositMined(ServerLevel level, BlockPos pos, ServerPlayer miner) {
      BlockPos key = null;

      for (BlockPos k : new HashSet<>(iceCubeDeposits.keySet())) {
         if (Math.abs(k.getX() - pos.getX()) <= 1 && Math.abs(k.getY() - pos.getY()) <= 1 && Math.abs(k.getZ() - pos.getZ()) <= 1) {
            key = k;
            break;
         }
      }

      if (key != null) {
         List<ItemStack> stacks = iceCubeDeposits.remove(key);
         iceCubeDepositOwners.remove(key);
         if (stacks != null) {
            for (ItemStack s : stacks) {
               giveOrCollect(miner, s);
            }

            Chat.raw(miner, "§b\u2744 The ice cracks open - the frozen gear is yours!");
         }

         for (int dx = 0; dx < 2; dx++) {
            for (int dy = 0; dy < 2; dy++) {
               for (int dz = 0; dz < 2; dz++) {
                  BlockPos b = key.offset(dx, dy, dz);
                  if (level.getBlockState(b).is(Blocks.ICE)) {
                     level.setBlock(b, Blocks.AIR.defaultBlockState(), 3);
                  }
               }
            }
         }
      }
   }

