   private static void transportToRealm(MinecraftServer server, ServerLevel level, Mob queen, ActiveBoss b) {
      try {
         ServerLevel realm = server.getLevel(SNOW_REALM);
         if (realm == null) {
            queen.setInvulnerable(false);
            b.snow.portalTicks = 0;
            return;
         }

         SnowState s = b.snow;
         double qx = queen.getX();
         double qz = queen.getZ();
         BlockPos spot = realmSurface(realm, 0, 0);
         paveRealmArena(realm, 0, 0);
         queen.teleport(
            new TeleportTransition(
               realm,
               new Vec3(spot.getX() + 0.5, spot.getY(), spot.getZ() + 0.5),
               Vec3.ZERO,
               queen.getYRot(),
               queen.getXRot(),
               TeleportTransition.PLACE_PORTAL_TICKET
            )
         );
         queen.setInvulnerable(false);
         s.inRealm = true;
         s.nextServants = ServerClock.clock(realm) + 40L;
         s.nextStorm = ServerClock.clock(realm) + 120L;
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.PORTAL, qx, queen.getY(), qz, 60, 2.0, 2.0, 2.0, 0.05);

         for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !isInSnowRealm(pl) && pl.distanceToSqr(qx, queen.getY(), qz) < 676.0)) {
            try {
               p.stopRiding();
               storeRealmReturn(p);
               BlockPos pp = realmSurface(realm, RANDOM.nextInt(17) - 8, RANDOM.nextInt(17) - 8);
               p.teleport(
                  new TeleportTransition(
                     realm, new Vec3(pp.getX() + 0.5, pp.getY(), pp.getZ() + 0.5), Vec3.ZERO, p.getYRot(), p.getXRot(), TeleportTransition.PLACE_PORTAL_TICKET
                  )
               );
               p.setDeltaMovement(0.0, 0.0, 0.0);
               // Three seconds of untouchable on arrival: the realm loads around you, nothing lands meanwhile.
               p.addEffect(new MobEffectInstance(MobEffects.RESISTANCE, 60, 4, false, false, true));
               com.fortuneandfavors.net.FfVfx.shape(realm, com.fortuneandfavors.net.FfVfx.WORMHOLE, ParticleTypes.SNOWFLAKE, p.position(), Vec3.ZERO, 0.0, 1.0, 0xBFEFFF);
               s.realmPlayers.add(p.getUUID());
               snowRealmPos.put(p.getUUID(), new double[]{p.getX(), p.getY(), p.getZ()});
               Chat.raw(
                  p,
                  "§b\u2744 You are torn into the Snow Queen's frozen realm! §7Her storms will freeze you over time - slay her to escape, or run §f/ff leaverealm§7 to slip back through the portal."
               );
               com.fortuneandfavors.net.FfVfx.particles(realm, ParticleTypes.SNOWFLAKE, p.getX(), p.getY() + 1.5, p.getZ(), 40, 1.0, 1.2, 1.0, 0.08);
            } catch (Exception var14) {
            }
         }

         level.playSound(null, qx, queen.getY(), qz, SoundEvents.ENDERMAN_TELEPORT, SoundSource.HOSTILE, 1.2F, 0.5F);
      } catch (Exception var15) {
      }
   }

   /** Builds the frozen arena. This used to only *re-texture* snow/ice/stone it
    *  found in the realm - but the realm is generated as a void flat world, so
    *  there was never a single block to convert and the arena shipped completely
    *  empty ("no blocks in the Snow Queen realm"). It now lays a real floor plus
    *  a low rim so nobody can walk off into the void during the fight. */
   private static void paveRealmArena(ServerLevel realm, int cx, int cz) {
      try {
         for (int cdx = -3; cdx <= 3; cdx++) {
            for (int cdz = -3; cdz <= 3; cdz++) {
               realm.getChunk(cx + cdx, cz + cdz);
            }
         }

         BlockState floor = Blocks.SNOW_BLOCK.defaultBlockState();
         BlockState sub = Blocks.PACKED_ICE.defaultBlockState();

         for (int dx = -REALM_ARENA_RADIUS; dx <= REALM_ARENA_RADIUS; dx++) {
            for (int dz = -REALM_ARENA_RADIUS; dz <= REALM_ARENA_RADIUS; dz++) {
               int gx = cx + dx;
               int gz = cz + dz;
               realm.setBlock(new BlockPos(gx, REALM_ARENA_Y, gz), floor, 2);
               realm.setBlock(new BlockPos(gx, REALM_ARENA_Y - 1, gz), sub, 2);
               realm.setBlock(new BlockPos(gx, REALM_ARENA_Y - 2, gz), sub, 2);

               boolean edge = dx == -REALM_ARENA_RADIUS
                  || dx == REALM_ARENA_RADIUS
                  || dz == -REALM_ARENA_RADIUS
                  || dz == REALM_ARENA_RADIUS;
               if (edge) {
                  for (int wy = 1; wy <= REALM_WALL_HEIGHT; wy++) {
                     realm.setBlock(new BlockPos(gx, REALM_ARENA_Y + wy, gz), sub, 2);
                  }
               }
            }
         }
      } catch (Exception var10) {
      }
   }

   public static void onRealmPlayerJoin(ServerPlayer p) {
      try {
         if (p == null || isInSnowRealm(p) || !snowQueenLive(p.level().getServer())) {
            return;
         }

         MinecraftServer server = p.level().getServer();

         for (Entry<UUID, ActiveBoss> entry : bosses.entrySet()) {
            ActiveBoss b = entry.getValue();
            if (b.snowQueen && b.snow != null && b.snow.realmPlayers.contains(p.getUUID())) {
               ServerLevel realm = server.getLevel(SNOW_REALM);
               if (realm == null) {
                  return;
               }

               LivingEntity queen = findEntity(server, entry.getKey()) instanceof LivingEntity le ? le : null;
               double[] saved = snowRealmPos.get(p.getUUID());
               double x;
               double y;
               double z;
               if (saved != null) {
                  x = saved[0];
                  y = saved[1];
                  z = saved[2];
               } else if (queen != null) {
                  x = queen.getX();
                  y = queen.getY();
                  z = queen.getZ();
               } else {
                  BlockPos spot = realmSurface(realm, 0, 0);
                  x = spot.getX() + 0.5;
                  y = spot.getY();
                  z = spot.getZ() + 0.5;
               }

               p.teleport(
                  new TeleportTransition(
                     realm, new Vec3(x, Math.max(y, realm.getMinY() + 4), z), Vec3.ZERO, p.getYRot(), p.getXRot(), TeleportTransition.PLACE_PORTAL_TICKET
                  )
               );
               Chat.raw(p, "§b\u2744 You re-enter the Snow Queen's frozen realm - §7the fight is still on!");
               com.fortuneandfavors.net.FfVfx.particles(realm, ParticleTypes.SNOWFLAKE, x, y + 1.5, z, 30, 0.8, 1.0, 0.8, 0.06);
               return;
            }
         }
      } catch (Exception var16) {
      }
   }

