   public static String escapeSnowRealm(ServerPlayer p) {
      try {
         if (p != null && isInSnowRealm(p)) {
            MinecraftServer server = p.level().getServer();
            ServerLevel overworld = server.overworld();
            ActiveBoss live = null;

            for (ActiveBoss b : bosses.values()) {
               if (b.snowQueen && b.snow != null && b.snow.realmPlayers.contains(p.getUUID())) {
                  live = b;
                  break;
               }
            }

            double x;
            double y;
            double z;
            if (live != null) {
               BlockPos home = realmSurface(overworld, (int)live.snow.portalX, (int)live.snow.portalZ);
               x = home.getX() + 0.5;
               y = home.getY();
               z = home.getZ() + 0.5;
            } else {
               CustomData d = (CustomData)p.get(DataComponents.CUSTOM_DATA);
               CompoundTag t = d != null ? d.copyTag() : new CompoundTag();
               if (t.contains("ff_realm_return_x")) {
                  x = t.getDouble("ff_realm_return_x").orElse(0.0);
                  y = t.getDouble("ff_realm_return_y").orElse(0.0);
                  z = t.getDouble("ff_realm_return_z").orElse(0.0);
               } else {
                  BlockPos spawn = overworld.getRespawnData().pos();
                  x = spawn.getX() + 0.5;
                  y = spawn.getY();
                  z = spawn.getZ() + 0.5;
               }
            }

            p.stopRiding();
            p.teleport(
               new TeleportTransition(
                  overworld, new Vec3(x, Math.max(y, overworld.getMinY() + 4), z), Vec3.ZERO, p.getYRot(), p.getXRot(), TeleportTransition.PLACE_PORTAL_TICKET
               )
            );
            p.setDeltaMovement(0.0, 0.0, 0.0);
            snowRealmPos.remove(p.getUUID());
            if (live != null) {
               live.snow.realmPlayers.remove(p.getUUID());
            }

            clearRealmReturn(p);
            Chat.raw(p, "§b\u2744 You slip through the rift and tumble back through the portal.");
            com.fortuneandfavors.net.FfVfx.particles(overworld, ParticleTypes.SNOWFLAKE, p.getX(), p.getY() + 1.5, p.getZ(), 30, 0.8, 1.0, 0.8, 0.06);
            return null;
         } else {
            return "You're not in the Snow Queen's realm.";
         }
      } catch (Exception ignored) {
         return "The rift is unsteady - try again in a moment.";
      }
   }

