   private static double[] puppetDodge(ServerLevel level, LivingEntity puppet, double nx, double nz) {
      try {
         if (RANDOM.nextDouble() >= 0.5) {
            return new double[]{nx, nz, 0.0};
         }

         Projectile threat = null;
         double bd = 42.25;

         for (Projectile proj : level.getEntitiesOfClass(
            Projectile.class, puppet.getBoundingBox().inflate(6.5), pr -> pr.isAlive() && !pr.getUUID().equals(puppet.getUUID())
         )) {
            Vec3 mv = proj.getDeltaMovement();
            if (!(mv.lengthSqr() <= 0.01) && !(puppet.position().subtract(proj.position()).dot(mv) <= 0.0)) {
               double d = proj.distanceToSqr(puppet);
               if (d < bd) {
                  bd = d;
                  threat = proj;
               }
            }
         }

         if (threat != null) {
            Vec3 mv = threat.getDeltaMovement().normalize();
            if (threat.getY() < puppet.getY() + 0.8) {
               return new double[]{nx, nz, 0.85};
            }

            return new double[]{nx - mv.z * (RANDOM.nextBoolean() ? 0.6 : -0.6), nz + mv.x * (RANDOM.nextBoolean() ? 0.6 : -0.6), 0.0};
         }
      } catch (Exception var14) {
      }

      return new double[]{nx, nz, 0.0};
   }

   private static boolean puppetHazardBelow(ServerLevel level, double x, double z, double startY) {
      int bx = (int)Math.floor(x);
      int bz = (int)Math.floor(z);

      for (int i = 1; i <= 10; i++) {
         int y = (int)Math.floor(startY) - i;
         if (y < level.getMinY()) {
            return true;
         }

         BlockPos pos = new BlockPos(bx, y, bz);
         BlockState state = level.getBlockState(pos);
         if (!state.getCollisionShape(level, pos).isEmpty()) {
            Fluid f = state.getFluidState().getType();
            return f == Fluids.LAVA || f == Fluids.FLOWING_LAVA;
         }
      }

      return true;
   }

   private static boolean puppetSolidAt(ServerLevel level, double x, double y, double z) {
      BlockPos pos = BlockPos.containing(x, y, z);
      if (pos.getY() < level.getMinY()) {
         return true;
      } else {
         return pos.getY() >= level.getMaxY() ? false : !level.getBlockState(pos).getCollisionShape(level, pos).isEmpty();
      }
   }

   private static double puppetGroundBelow(ServerLevel level, double x, double z, double startY) {
      int bx = (int)Math.floor(x);
      int bz = (int)Math.floor(z);
      int by = (int)Math.floor(startY);

      for (int i = 0; i < 6; i++) {
         int y = by - i;
         if (y < level.getMinY()) {
            break;
         }

         BlockPos pos = new BlockPos(bx, y, bz);
         VoxelShape shape = level.getBlockState(pos).getCollisionShape(level, pos);
         if (!shape.isEmpty()) {
            return y + shape.max(Axis.Y);
         }
      }

      return startY;
   }

   private static boolean puppetInFluid(ServerLevel level, double x, double y, double z) {
      BlockPos pos = BlockPos.containing(x, y + 0.2, z);
      return !level.getBlockState(pos).getFluidState().isEmpty();
   }

   private static boolean puppetFight(ServerLevel level, LivingEntity puppet, LivingEntity target, ItemStack held, long now, ServerPlayer victim) {
      try {
         if (target == null || held.isEmpty()) {
            return false;
         }

         Item item = held.getItem();
         double dist = puppet.distanceTo(target);
         ItemCooldowns cooldowns = victim.getCooldowns();
         if (cooldowns != null && cooldowns.isOnCooldown(held)) {
            return false;
         }

         if (item instanceof BowItem && dist > 3.5 && dist < 26.0 && now >= puppetRangedCd.getOrDefault(puppet.getUUID(), 0L)) {
            Arrow arrow = new Arrow(level, puppet, new ItemStack(Items.ARROW), held.copy());
            arrow.shootFromRotation(puppet, puppet.getXRot(), puppet.getYRot(), 0.0F, 2.6F, 2.0F);
            arrow.setBaseDamage(6.0 + Math.max(0, ModItems.tierOf(held) - 1) * 0.75);
            arrow.setCritArrow(true);
            level.addFreshEntity(arrow);
            level.playSound(null, puppet.getX(), puppet.getY(), puppet.getZ(), SoundEvents.ARROW_SHOOT, SoundSource.HOSTILE, 1.0F, 0.9F);
            puppetRangedCd.put(puppet.getUUID(), now + 26L);
            puppetCooldown(cooldowns, held, 18);
            return true;
         }

         if (item instanceof CrossbowItem && dist > 3.5 && dist < 26.0 && now >= puppetRangedCd.getOrDefault(puppet.getUUID(), 0L)) {
            Arrow bolt = new Arrow(level, puppet, new ItemStack(Items.ARROW), held.copy());
            bolt.shootFromRotation(puppet, puppet.getXRot(), puppet.getYRot(), 0.0F, 3.2F, 1.0F);
            bolt.setBaseDamage(7.0 + Math.max(0, ModItems.tierOf(held) - 1) * 0.75);
            bolt.setCritArrow(true);
            level.addFreshEntity(bolt);
            level.playSound(null, puppet.getX(), puppet.getY(), puppet.getZ(), SoundEvents.CROSSBOW_SHOOT, SoundSource.HOSTILE, 1.0F, 1.0F);
            puppetRangedCd.put(puppet.getUUID(), now + 34L);
            puppetCooldown(cooldowns, held, 22);
            return true;
         }

         if (item instanceof TridentItem && dist > 3.0 && dist < 16.0 && now % 32L == 0L) {
            ThrownTrident trident = new ThrownTrident(level, puppet, held.copy());
            trident.shootFromRotation(puppet, puppet.getXRot(), puppet.getYRot(), 0.0F, 2.2F, 2.5F);
            trident.setBaseDamage(9.0);
            level.addFreshEntity(trident);
            level.playSound(null, puppet.getX(), puppet.getY(), puppet.getZ(), SoundEvents.TRIDENT_THROW, SoundSource.HOSTILE, 1.0F, 1.0F);
            puppetCooldown(cooldowns, held, 20);
            return true;
         }

         if ((item instanceof SplashPotionItem || item instanceof LingeringPotionItem) && dist > 2.0 && dist < 9.0 && now % 40L == 0L) {
            AbstractThrownPotion potion;
            if (item instanceof LingeringPotionItem) {
               potion = new ThrownLingeringPotion(level, puppet, held.copy());
            } else {
               potion = new ThrownSplashPotion(level, puppet, held.copy());
            }

            potion.shootFromRotation(puppet, puppet.getXRot(), puppet.getYRot(), -8.0F, 0.65F, 3.0F);
            level.addFreshEntity(potion);
            puppetCooldown(cooldowns, held, 20);
            return true;
         }

         if (puppet.getHealth() < puppet.getMaxHealth() * 0.65 && now % 30L == 0L) {
            FoodProperties food = (FoodProperties)held.get(DataComponents.FOOD);
            if (food != null) {
               Consumable consume = new Consumable(1.6F, ItemUseAnimation.EAT, SoundEvents.GENERIC_EAT, true, List.of());
               food.onConsume(level, puppet, held, consume);
               level.playSound(null, puppet.getX(), puppet.getY(), puppet.getZ(), SoundEvents.GENERIC_EAT, SoundSource.HOSTILE, 1.0F, 1.0F);
               puppetCooldown(cooldowns, held, 10);
               return true;
            }
         }

         if ((item instanceof EnderpearlItem || item instanceof SnowballItem || item instanceof EggItem) && dist > 2.0 && dist < 14.0 && now % 24L == 0L) {
            if (!consumeFromInventory(victim, item)) {
               return false;
            }

            Projectile proj;
            if (item instanceof EnderpearlItem) {
               proj = new ThrownEnderpearl(level, puppet, new ItemStack(Items.ENDER_PEARL));
            } else if (item instanceof EggItem) {
               proj = new ThrownEgg(level, puppet, new ItemStack(Items.EGG));
            } else {
               proj = new Snowball(level, puppet, new ItemStack(Items.SNOWBALL));
            }

            proj.shootFromRotation(puppet, puppet.getXRot(), puppet.getYRot(), 0.0F, 1.5F, 1.0F);
            level.addFreshEntity(proj);
            puppetCooldown(cooldowns, held, 16);
            return true;
         }
      } catch (Exception var13) {
      }

      return false;
   }

   private static boolean consumeFromInventory(ServerPlayer victim, Item item) {
      try {
         Inventory inv = victim.getInventory();

         for (int i = 0; i < inv.getContainerSize(); i++) {
            ItemStack s = inv.getItem(i);
            if (!s.isEmpty() && s.getItem() == item) {
               s.shrink(1);
               return true;
            }
         }
      } catch (Exception var5) {
      }

      return false;
   }

