   public static String garbleChat(String msg, int stage) {
      if (msg != null && !msg.isEmpty()) {
         char[] c = msg.toCharArray();

         int swaps = switch (stage) {
            case 1 -> Math.max(1, c.length / 6);
            case 2 -> Math.max(3, c.length / 3);
            default -> Math.max(6, c.length / 2);
         };

         for (int i = 0; i < swaps && i < c.length; i++) {
            int idx = RANDOM.nextInt(c.length);
            if (stage >= 3) {
               c[idx] = "¤¥§æœ◊∆‡".charAt(RANDOM.nextInt(7));
            } else if (idx + 1 < c.length && RANDOM.nextBoolean()) {
               char t = c[idx];
               c[idx] = c[idx + 1];
               c[idx + 1] = t;
            } else {
               c[idx] = c[idx] == ' ' ? c[idx] : (char)(c[idx] + (RANDOM.nextBoolean() ? 1 : -1));
            }
         }

         return new String(c);
      } else {
         return msg;
      }
   }

   private static void tickSanity(ServerLevel level, ServerPlayer p, int lvl, long now) {
      try {
         if (p == null || !p.isAlive()) {
            return;
         }

         int s = sanity.getOrDefault(p.getUUID(), 100);

         int perSecond = switch (lvl) {
            case 1 -> 10;
            case 2 -> 20;
            default -> 40;
         };
         if (now % 20L == 0L) {
            s = Math.max(0, s - perSecond);
         }

         if (s <= 0) {
            boolean seeingVision = mindHallucActiveUntil.getOrDefault(p.getUUID(), 0L) > now;
            if (seeingVision) {
               p.hurtServer(level, level.damageSources().magic(), 8.0F);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, p.getX(), p.getY() + 1.2, p.getZ(), 26, 0.6, 0.8, 0.6, 0.05);
               level.playSound(null, p.getX(), p.getY(), p.getZ(), SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 1.0F, 0.4F);
               actionBar(p, "§cYour mind splinters - §7the vision cuts you!");
               s = 40;
            } else {
               s = 60;
            }
         }

         sanity.put(p.getUUID(), Math.min(100, s));
      } catch (Exception var8) {
      }
   }

   private static void applyCorruptionStage(ServerLevel level, ServerPlayer p, int lvl, long now) {
      if (lvl == 1) {
         p.addEffect(new MobEffectInstance(MobEffects.NAUSEA, 60, 0, false, false));
         p.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 80, 0, false, false));
         p.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 80, 0, false, false));
         if (now % 40L == 0L) {
            p.setDeltaMovement(
               (RANDOM.nextBoolean() ? 1 : -1) * (0.25 + RANDOM.nextDouble() * 0.35),
               0.12,
               (RANDOM.nextBoolean() ? 1 : -1) * (0.25 + RANDOM.nextDouble() * 0.35)
            );
            p.hurtMarked = true;
         }
      } else if (lvl == 2) {
         if (now % 320L == 0L) {
            triggerMindbinderHallucination(level, p, now);
         }

         p.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 80, 1, false, false));
         p.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 80, 1, false, false));
         p.addEffect(new MobEffectInstance(MobEffects.NAUSEA, 60, 0, false, false));
         if (now % 20L == 0L) {
            LivingEntity ally = nearestAlly(p);
            if (ally != null) {
               Vec3 to = ally.position().subtract(p.position()).normalize();
               p.setDeltaMovement(to.x * 0.35, 0.1, to.z * 0.35);
               p.hurtMarked = true;
               if (ally instanceof ServerPlayer allyP) {
                  UUID last = mindSnapTarget.get(p.getUUID());
                  if (last == null || !last.equals(allyP.getUUID())) {
                     mindSnapTarget.put(p.getUUID(), allyP.getUUID());
                     snapPlayerViewToward(p, allyP);
                  }
               }
            }
         }

         if (now % 16L == 0L) {
            LivingEntity lash = mindPuppetVictim(p);
            if (lash != null && p.distanceToSqr(lash) < 11.559999999999999 && !(lash instanceof ServerPlayer vp && !ClaimManager.pvpAllowed(p, vp))) {
               try {
                  level.getServer().getPlayerList().broadcastAll(new ClientboundAnimatePacket(p, 0));
               } catch (Exception var9) {
               }

               float dmg = weaponDamage(level, p, p.getMainHandItem(), lash);
               lash.hurtServer(level, level.damageSources().playerAttack(p), dmg);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIT, lash.getX(), lash.getY() + 1.0, lash.getZ(), 6, 0.4, 0.5, 0.4, 0.1);
               if (now % 48L == 0L) {
                  actionBar(p, "§5Your arm moves on its own...");
               }
            }
         }
      } else if (lvl >= 3 && !wearsPossessedMask(p)) {
         p.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 60, 255, false, false));
         p.setDeltaMovement(0.0, 0.0, 0.0);
         p.hurtMarked = true;
         if (now % 5L == 0L) {
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.ENCHANT, p.getX(), p.getY() + 2.1, p.getZ(), 4, 0.25, 0.1, 0.25, 0.0);
         }
      }

      corruptionHeadFx(level, p, lvl, now);
   }

   private static void corruptionHeadFx(ServerLevel level, ServerPlayer p, int lvl, long now) {
      try {
         if (lvl >= 3 && wearsPossessedMask(p)) {
            return;
         }

         int count;
         double radius;
         float size;
         float hue;
         int freq;
         switch (lvl) {
            case 1:
               count = 3;
               radius = 0.24;
               size = 0.8F;
               hue = 0.72F;
               freq = 10;
               break;
            case 2:
               count = 5;
               radius = 0.32;
               size = 1.0F;
               hue = 0.82F;
               freq = 6;
               break;
            default:
               count = 7;
               radius = 0.4;
               size = 1.3F;
               hue = 0.95F;
               freq = 4;
         }

         if (now % freq != 0L) {
            return;
         }

         long step = now / freq;

         for (int i = 0; i < count; i++) {
            double a = step * 0.3 + i * ((Math.PI * 2) / count);
            int color = Color.HSBtoRGB(hue, 0.85F, 1.0F) & 16777215;
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(color, size),
               p.getX() + Math.cos(a) * radius,
               p.getY() + 2.15 + Math.sin(step * 0.18 + i * 1.7) * 0.14,
               p.getZ() + Math.sin(a) * radius,
               1,
               0.02,
               0.02,
               0.02,
               0.0
            );
         }

         if (lvl >= 3) {
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(16720000, 1.0F), p.getX(), p.getY() + 2.3, p.getZ(), 2, 0.28, 0.06, 0.28, 0.0);
         }
      } catch (Exception var17) {
      }
   }

   public static String testCorruption(ServerPlayer p, int stage) {
      try {
         if (stage >= 1 && stage <= 3) {
            testCorruptionStage.put(p.getUUID(), stage);
            testCorruptionUntil.put(p.getUUID(), ServerClock.clock(p.level()) + 400L);
            if (stage >= 3) {
               spawnMindPuppet(p);
            }

            sendCorruptionFx(p, true);
            return null;
         } else {
            return "Stage must be 1, 2 or 3.";
         }
      } catch (Exception e) {
         return "Something went wrong applying test corruption.";
      }
   }

   public static void tickTestCorruption(MinecraftServer server) {
      try {
         for (Entry<UUID, Integer> e : new HashMap<>(testCorruptionStage).entrySet()) {
            ServerPlayer p = server.getPlayerList().getPlayer(e.getKey());
            Long until = testCorruptionUntil.get(e.getKey());
            if (p != null && p.isAlive() && until != null) {
               ServerLevel level = p.level();
               long now = ServerClock.clock(level);
               if (now >= until) {
                  clearTestCorruption(server, e.getKey());
                  if (e.getValue() >= 3) {
                     corruptionBreakBurst(p);
                  }

                  actionBar(p, "§aTest corruption cleared.");
               } else {
                  applyCorruptionStage(level, p, e.getValue(), now);
                  tickSanity(level, p, e.getValue(), now);
                  if (e.getValue() >= 3) {
                     if (!mindPuppets.containsKey(p.getUUID())) {
                        spawnMindPuppet(p);
                     }

                     long meter = mindStruggleMeter.getOrDefault(p.getUUID(), 480L);
                     meter = Math.min(480L, meter + 1L);
                     if (p.getLastClientInput() != null && p.getLastClientInput().jump()) {
                        long last = mindMashTick.getOrDefault(p.getUUID(), 0L);
                        if (now - last >= 10L) {
                           mindMashTick.put(p.getUUID(), now);
                           meter = Math.max(0L, meter - 24L);
                           com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIT, p.getX(), p.getY() + 1.2, p.getZ(), 8, 0.4, 0.5, 0.4, 0.1);
                           level.playSound(null, p.getX(), p.getY(), p.getZ(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.HOSTILE, 0.9F, 1.6F);
                        }
                     } else {
                        mindMashTick.put(p.getUUID(), now - 10L);
                     }

                     mindStruggleMeter.put(p.getUUID(), meter);
                     if (meter <= 0L) {
                        clearTestCorruption(server, e.getKey());
                        corruptionBreakBurst(p);
                        actionBar(p, "§aYou wrench free - the hold breaks!");
                        continue;
                     }

                     showStruggleBar(p, meter, heldBodyBarName(server, p));
                     if (now % 20L == 0L) {
                        drainCorruptionStep(level, p);
                        actionBar(p, "§cThe Mindbinder drinks your life! §7mash JUMP to break free");
                     }
                  }

                  if (now % 20L == 0L) {
                     sendCorruptionFx(p, true);

                     String stage = switch (e.getValue()) {
                        case 1 -> "§5§lCORRUPTION I - §fConfusion";
                        case 2 -> "§5§lCORRUPTION II - §fPuppet";
                        default -> "§c§lCORRUPTION III - §fFull Control";
                     };
                     updateCorruptionBar(p, e.getValue(), until - now, stage + " §7for " + (until - now + 19L) / 20L + "s");
                  }
               }
            } else {
               clearTestCorruption(server, e.getKey());
            }
         }
      } catch (Exception var16) {
      }
   }

   private static void clearTestCorruption(MinecraftServer server, UUID player) {
      testCorruptionStage.remove(player);
      testCorruptionUntil.remove(player);
      removeCorruptionBar(player);
      sanity.remove(player);
      mindHallucActiveUntil.remove(player);
      ServerPlayer p = server.getPlayerList().getPlayer(player);
      if (p != null) {
         p.removeEffect(MobEffects.NAUSEA);
         p.removeEffect(MobEffects.SLOWNESS);
         p.removeEffect(MobEffects.WEAKNESS);
         sendCorruptionFx(p, false);
      }

      releaseMindPuppet(server, player);
   }

   /**
    * One move of the Mindbinder's rotation: what the room is told, and how long the room has to
    * answer it.
    *
    * @param id        the id the switch in {@link #mindStartMove} knows
    * @param tell      the name of the move, shouted at the room as the telegraph
    * @param counter   the answer the room has to give, in as few words as possible
    * @param tellTicks how long the telegraph runs before the move lands
    * @param slotTicks how long the move owns after it starts - nothing else begins until it is up
    */
   private record MindMove(String id, String tell, String counter, int tellTicks, int slotTicks) {
   }

   private static final MindMove MIND_LIGHTNING = new MindMove("lightning", "SNAP OF STATIC", "get off the marked ground", 22, 26);
   private static final MindMove MIND_MINE = new MindMove("mine", "BURIED THOUGHTS", "watch your feet", 24, 40);
   private static final MindMove MIND_FIREBURST = new MindMove("fireburst", "PYRE", "spread out", 22, 26);
   private static final MindMove MIND_WATERBEAM = new MindMove("waterbeam", "BROKEN FLOW", "keep moving", 20, 26);
   private static final MindMove MIND_BARRAGE = new MindMove("barrage", "BARRAGE", "use the cover", 18, 30);
   private static final MindMove MIND_STARE = new MindMove("stare", "THE LONG STARE", "break the line of sight", 24, 70);
   private static final MindMove MIND_CLONES = new MindMove("clones", "ECHOES", "find the one that bleeds", 22, 60);
   private static final MindMove MIND_HANDS = new MindMove("hands", "VOID HANDS", "keep moving, share the hold", 20, 40);
   private static final MindMove MIND_QTE = new MindMove("qte", "MIND GRIP", "get ready to SNEAK", 16, 60);
   private static final MindMove MIND_QUAKE = new MindMove("quake", "TREMOR", "get off the ground - jump the ring", 24, 80);
   private static final MindMove MIND_WAVE = new MindMove("wave", "CORRUPTION WAVE", "leave the ring", 22, 60);
   private static final MindMove MIND_ULTIMATE = new MindMove("ultimate", "UNMADE", "run - the whole room is the blast", 30, 95);
   private static final MindMove MIND_MAELSTROM = new MindMove("maelstrom", "MAELSTROM", "find the gap and stay in it", 26, 55);
   private static final MindMove MIND_BEAM = new MindMove("beam", "SHARED MIND", "do not stand beside your friend", 22, 70);
   private static final MindMove MIND_FRACTURE = new MindMove("fracture", "FRACTURE", "look away from him", 20, 50);

   /**
    * The three rotations, one per phase, in order.
    *
    * <p>An order rather than a coin toss, because an order can be learned: the first phase is the
    * four cheap spells that teach what a tell looks like, the second adds the arena - a ring to
    * leave, a wave to leave, a body to find - and the last is the fight's own endgame, led by the
    * move that unmakes the room. The list wraps, so nothing is ever a dead end and nothing is ever
    * unpredictable; the only thing that changes between laps is how fast the room has to answer.
    */
   private static final List<MindMove> MIND_ROTATION_1 = List.of(MIND_LIGHTNING, MIND_MINE, MIND_FIREBURST, MIND_STARE);
   private static final List<MindMove> MIND_ROTATION_2 = List.of(
      MIND_QUAKE, MIND_WATERBEAM, MIND_FRACTURE, MIND_CLONES, MIND_WAVE, MIND_HANDS, MIND_QTE, MIND_LIGHTNING
   );
   private static final List<MindMove> MIND_ROTATION_3 = List.of(
      MIND_ULTIMATE, MIND_MAELSTROM, MIND_FRACTURE, MIND_BEAM, MIND_QTE, MIND_WAVE, MIND_QUAKE, MIND_CLONES, MIND_FRACTURE
   );

   private static final Map<String, MindMove> MIND_MOVES = mindMoveIndex();

   private static Map<String, MindMove> mindMoveIndex() {
      Map<String, MindMove> out = new HashMap<>();
      for (List<MindMove> rotation : List.of(MIND_ROTATION_1, MIND_ROTATION_2, MIND_ROTATION_3)) {
         for (MindMove move : rotation) {
            out.put(move.id(), move);
         }
      }
      return out;
   }

   /** Which third of the fight this is - the same borders the rotation changes on. */
   public static int mindStage(Mob witch) {
      if (witch == null) {
         return 1;
      }
      float max = Math.max(1.0F, witch.getMaxHealth());
      float hp = witch.getHealth();
      if (hp <= max * 0.3F) {
         return 3;
      }
      return hp <= max * 0.66F ? 2 : 1;
   }

   private static List<MindMove> mindRotationFor(int stage) {
      return stage >= 3 ? MIND_ROTATION_3 : (stage == 2 ? MIND_ROTATION_2 : MIND_ROTATION_1);
   }

   /** The beat between one move ending and the next tell starting. */
   private static long mindGapFor(int stage) {
      return stage >= 3 ? 22L : (stage == 2 ? 32L : 44L);
   }

   /**
    * The Mindbinder's whole schedule: tell, move, beat, next.
    *
    * <p>Exactly one thing is ever happening. While a tell runs it is the move - the room is being
    * told what is coming and what answers it - and while a move runs it owns the witch until its
    * slot is up, when every one of its fields is cleared so nothing can trail into the next beat.
    * The old fight could run three of these at once, which is how a fight becomes a wall of
    * particle effects rather than a set of problems.
    */
   public static void mindRotation(MinecraftServer server, ServerLevel level, Mob witch, ActiveBoss b, long now) {
      if (b == null || b.mind == null || witch == null) {
         return;
      }

      MindState m = b.mind;
      int stage = mindStage(witch);

      if (!m.phase3 && stage >= 3) {
         m.phase3 = true;
         m.step = 0;
         b.bar.setColor(BossBarColor.RED);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL_FIRE_FLAME, witch.getX(), witch.getY() + 1.4, witch.getZ(), 80, 1.2, 1.4, 1.2, 0.06);
         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WITHER_SPAWN, SoundSource.HOSTILE, 1.0F, 0.7F);
         m.speech.add("Enough. I'll wear all of you at once.");
         m.nextSpeech = Math.min(m.nextSpeech, now + 5L);
      }

      if (m.tellMove != null) {
         mindTellTick(level, witch, m, now);
         if (now >= m.tellUntil) {
            String move = m.tellMove;
            m.tellMove = null;
            mindStartMove(server, level, witch, b, now, move);
         }
         return;
      }

      if (m.activeMove != null) {
         if (now < m.activeUntil) {
            return;
         }
         m.activeMove = null;
         mindForceEnd(m);
         m.nextMove = now + mindGapFor(stage);
         return;
      }

      // Not isNoAi(): the Mindbinder is always NoAi (it is moved by hand), so that gate stopped every move.
      if (m.stunUntil > now || m.qteActive || m.beamUntil > now) {
         return;
      }
      if (now < Math.max(m.nextMove, m.nextSpell)) {
         return;
      }

      List<MindMove> rotation = mindRotationFor(stage);
      MindMove move = rotation.get(Math.floorMod(m.step, rotation.size()));
      m.step++;
      m.tellMove = move.id();
      m.tellUntil = now + move.tellTicks();
      mindTellStart(level, witch, move);
   }

   /**
    * Starts the move a tell was announcing, and takes ownership of the witch for its slot.
    *
    * <p>The move functions themselves are unchanged: they are the "how", the rotation is the
    * "when", and the split is what lets a move be re-timed without being rewritten.
    */
   private static final int MIND_VIOLET = 0xB04CFF;

   /** Each spell's psychic mark, so no two of his moves look alike. */
   private static void mindSignature(ServerLevel level, Mob witch, String id) {
      Vec3 at = witch.position();
      switch (id) {
         case "lightning", "barrage" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.NOVA, ParticleTypes.ELECTRIC_SPARK, at, Vec3.ZERO, 4.0, 0.0, 0xB8A8FF);
         case "fireburst" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.NOVA, ParticleTypes.FLAME, at, Vec3.ZERO, 5.0, 0.0, 0xFF6A3C);
         case "waterbeam", "beam" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.PILLAR, ParticleTypes.END_ROD, at, Vec3.ZERO, 6.0, 0.0, 0x6FC8FF);
         case "mine", "quake" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.SUMMON_CIRCLE, ParticleTypes.PORTAL, at, Vec3.ZERO, 3.0, 24, MIND_VIOLET);
         case "stare", "hands", "qte" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.TEAR, ParticleTypes.PORTAL, at.add(0.0, 2.2, 0.0), new Vec3(1.0, 0.0, 0.0), 1.2, 30, MIND_VIOLET);
         case "clones" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.WORMHOLE, ParticleTypes.PORTAL, at, Vec3.ZERO, 0.0, 1.0, MIND_VIOLET);
         case "wave", "maelstrom", "ultimate" -> com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.CLOCK_BURST, ParticleTypes.PORTAL, at.add(0.0, 1.0, 0.0), Vec3.ZERO, 10.0, 0.0, MIND_VIOLET);
         default -> {
         }
      }
   }

   /** FRACTURE: anyone looking at him when it lands has their mind cracked. Turning away is the answer. */
   private static List<ServerPlayer> mindFracture(ServerLevel level, Mob witch) {
      List<ServerPlayer> struck = new ArrayList<>();
      com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.TEAR, ParticleTypes.PORTAL, witch.position().add(0.0, 1.6, 0.0), new Vec3(0.0, 0.0, 1.0), 2.4, 20, MIND_VIOLET);
      com.fortuneandfavors.net.FfVfx.shape(level, com.fortuneandfavors.net.FfVfx.NOVA, ParticleTypes.PORTAL, witch.position(), Vec3.ZERO, 12.0, 0.0, MIND_VIOLET);
      level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.ELDER_GUARDIAN_CURSE, SoundSource.HOSTILE, 1.4F, 1.3F);
      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator() && pl.distanceToSqr(witch) < 24.0 * 24.0)) {
         Vec3 toHim = witch.getEyePosition().subtract(p.getEyePosition()).normalize();
         if (p.getLookAngle().dot(toHim) < 0.5) {
            continue;
         }
         p.hurtServer(level, level.damageSources().indirectMagic(witch, witch), 6.0F);
         p.addEffect(new MobEffectInstance(MobEffects.NAUSEA, 70, 0, false, false));
         p.addEffect(new MobEffectInstance(MobEffects.DARKNESS, 40, 0, false, false));
         com.fortuneandfavors.net.FfNet.send(p, new com.fortuneandfavors.net.FfScreenFxPayload(com.fortuneandfavors.net.FfScreenFxPayload.FX_FRACTURE, true));
         struck.add(p);
      }
      return struck;
   }

   public static void mindStartMove(MinecraftServer server, ServerLevel level, Mob witch, ActiveBoss b, long now, String id) {
      MindState m = b.mind;
      mindForceEnd(m);
      mindSignature(level, witch, id == null ? "" : id);

      switch (id == null ? "" : id) {
         case "fracture" -> {
            for (ServerPlayer struck : mindFracture(level, witch)) {
               corrupt(b, level, struck);
            }
         }
         case "lightning" -> mindLightning(level, witch, b, now);
         case "fireburst" -> mindFireburst(level, witch, b, now);
         case "waterbeam" -> mindWaterbeam(level, witch, b, now);
         case "barrage" -> mindBarrage(level, witch, b, now);
         case "mine" -> mindMine(level, witch, b, now);
         case "stare" -> startMindStare(level, witch, b, now);
         case "clones" -> spawnMindClones(server, level, witch, b, now);
         case "hands" -> spawnVoidHand(level, witch, b, now);
         case "qte" -> startMindQte(server, level, witch, b, now);
         case "quake" -> mindQuake(level, witch, b, now);
         case "wave" -> mindCorruptionWave(level, witch, b, now);
         case "ultimate" -> mindUltimate(level, witch, b, now);
         case "beam" -> startSharedMind(server, level, witch, b, now);
         default -> mindMaelstrom(level, witch, b, now);
      }

      MindMove move = MIND_MOVES.get(id);
      m.activeMove = id == null ? "maelstrom" : id;
      m.activeUntil = now + (move == null ? 50 : move.slotTicks());
   }

   /**
    * Ends every field a move owns, so nothing outlives its slot.
    *
    * <p>The moves were written to clean up after themselves, and a move that is cut short - or a
    * move whose own window is longer than its slot - leaves its radius, its hit set or its stare
    * live behind the next one. Clearing them here is what makes "one move at a time" true rather
    * than merely intended.
    */
   private static void mindForceEnd(MindState m) {
      m.quakeUntil = 0L;
      m.quake2At = 0L;
      m.quakeHits.clear();
      m.waveUntil = 0L;
      m.waveHits.clear();
      m.maelstromUntil = 0L;
      m.ultimateUntil = 0L;
      m.ultimateR = 0.0;
      m.stareUntil = 0L;
      m.stareVictim = null;
      m.stareAccum.clear();
   }

   /** The tell: the name, the answer, and a ring on the ground that closes as the clock runs. */
   private static void mindTellStart(ServerLevel level, Mob witch, MindMove move) {
      try {
         mindCastFx(level, witch);
         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WARDEN_NEARBY_CLOSEST, SoundSource.HOSTILE, 1.0F, 1.5F);
         // Telegraph UI popup/actionbar removed per request
      } catch (Throwable ignored) {
      }
   }

   private static void mindTellTick(ServerLevel level, Mob witch, MindState m, long now) {
      if (now % 2L != 0L) {
         return;
      }

      double left = Math.max(0L, m.tellUntil - now);
      double r = 1.0 + left * 0.4;
      int count = Math.max(10, (int)(r * Math.PI * 2.0 / 1.1));

      for (int i = 0; i < count; i++) {
         double a = (double)i / count * Math.PI * 2.0 + now * 0.03;
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL_FIRE_FLAME, witch.getX() + Math.cos(a) * r, witch.getY() + 0.2, witch.getZ() + Math.sin(a) * r, 1, 0.03, 0.03, 0.03, 0.0
         );
      }

      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, witch.getX(), witch.getY() + 1.9, witch.getZ(), 2, 0.3, 0.3, 0.3, 0.01);
   }

   /** The move being telegraphed right now, for the readout and the self-test. */
   public static String mindTelegraphOf(ActiveBoss b) {
      return b == null || b.mind == null ? null : b.mind.tellMove;
   }

   /** The rotation order this phase runs, for the readout and the self-test. */
   public static List<String> mindRotationIds(int stage) {
      List<String> out = new ArrayList<>();
      for (MindMove move : mindRotationFor(stage)) {
         out.add(move.id());
      }
      return out;
   }

   /**
    * Every move the rotation can schedule, with the tell it announces itself with.
    *
    * <p>Pinned by {@code mindbinder.every-move-tells-before-it-lands}, because "a move with a
    * tell" is a promise the whole rework rests on and the easy way to break it is to add a
    * fourteenth move to a switch and forget the line the room has to read.
    */
   public static List<String> mindMoveTells() {
      List<String> out = new ArrayList<>();
      for (MindMove move : MIND_MOVES.values()) {
         out.add(move.id() + "|" + move.tell() + "|" + move.counter() + "|" + move.tellTicks() + "|" + move.slotTicks());
      }
      return out;
   }

   private static void mindLightning(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 30.0);
      if (target != null) {
         mindCastFx(level, witch);
         int strikes = b.mind.phase2 ? 4 : 3;
         float per = b.mind.phase2 ? 7.0F : 6.0F;

         for (int s = 0; s < strikes; s++) {
            double ang = (double)s / strikes * Math.PI * 2.0 + RANDOM.nextDouble() * 0.8;
            double sx = target.getX() + Math.cos(ang) * (1.2 + RANDOM.nextDouble() * 2.2);
            double sz = target.getZ() + Math.sin(ang) * (1.2 + RANDOM.nextDouble() * 2.2);

            for (int i = 0; i < 12; i++) {
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, sx, target.getY() + i * 0.6, sz, 2, 0.12, 0.1, 0.12, 0.01);
            }
         }

         level.playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 1.0F, 0.4F);

         for (int s = 0; s < strikes; s++) {
            double ang = (double)s / strikes * Math.PI * 2.0 + RANDOM.nextDouble() * 0.8;
            double sx = target.getX() + Math.cos(ang) * (1.2 + RANDOM.nextDouble() * 2.2);
            double sz = target.getZ() + Math.sin(ang) * (1.2 + RANDOM.nextDouble() * 2.2);
            LightningBolt bolt = (LightningBolt)EntityTypes.LIGHTNING_BOLT.create(level, EntitySpawnReason.TRIGGERED);
            if (bolt != null) {
               bolt.setVisualOnly(true);
               bolt.setPos(sx, target.getY(), sz);
               level.addFreshEntity(bolt);
            }

            for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && pl.distanceToSqr(sx, pl.getY(), sz) < 6.760000000000001)) {
               p.hurtServer(level, level.damageSources().mobAttack(witch), per);
            }

            level.playSound(null, sx, target.getY(), sz, SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.HOSTILE, 1.0F, 0.8F);
         }

         com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.4F), target.getX(), target.getY() + 1.0, target.getZ(), 14, 0.7, 0.7, 0.7, 0.05);
      }
   }

   private static void mindFireburst(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 30.0);
      if (target != null) {
         mindCastFx(level, witch);
         double r = b.mind.phase2 ? 4.2 : 3.4;
         float dmg = b.mind.phase2 ? 12.0F : 10.0F;

         for (int i = 0; i < 16; i++) {
            double a = i / 16.0 * Math.PI * 2.0;
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.FLAME, target.getX() + Math.cos(a) * r, target.getY() + 0.5, target.getZ() + Math.sin(a) * r, 3, 0.3, 0.2, 0.3, 0.03
            );
         }

         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.FLAME, target.getX(), target.getY() + 1.0, target.getZ(), 60, r, 1.0, r, 0.12);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.LAVA, target.getX(), target.getY() + 0.5, target.getZ(), 30, r * 0.7, 0.6, r * 0.7, 0.1);
         level.playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.GENERIC_EXPLODE, SoundSource.HOSTILE, 1.0F, 0.5F);

         for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && pl.distanceToSqr(target.getX(), pl.getY(), target.getZ()) < r * r)) {
            p.hurtServer(level, level.damageSources().mobAttack(witch), dmg);
            p.igniteForTicks(80);
         }
      }
   }

   private static void mindWaterbeam(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 30.0);
      if (target != null) {
         mindCastFx(level, witch);
         Vec3 a = witch.getEyePosition();
         Vec3 bv = target.getEyePosition();

         for (int i = 0; i <= 16; i++) {
            Vec3 pv = a.lerp(bv, i / 16.0);
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.DRIPPING_WATER, pv.x, pv.y, pv.z, 3, 0.2, 0.2, 0.2, 0.02);
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, pv.x, pv.y, pv.z, 1, 0.1, 0.1, 0.1, 0.01);
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-12533505, 0.9F), pv.x, pv.y, pv.z, 1, 0.08, 0.08, 0.08, 0.0);
         }

         level.playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.CONDUIT_ACTIVATE, SoundSource.HOSTILE, 1.0F, 0.6F);
         target.hurtServer(level, level.damageSources().mobAttack(witch), b.mind.phase2 ? 13.0F : 10.0F);
         com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-12533505, 1.3F), target.getX(), target.getY() + 1.0, target.getZ(), 16, 0.6, 0.6, 0.6, 0.05);
      }
   }

   private static void mindBarrage(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 34.0);
      if (target != null) {
         mindCastFx(level, witch);
         int shots = b.mind.phase2 ? 6 : 4;
         long fuse = now + (b.mind.phase2 ? 18 : 24);
         float dmg = b.mind.phase2 ? 7.0F : 6.0F;

         for (int s = 0; s < shots; s++) {
            double ang = RANDOM.nextDouble() * Math.PI * 2.0;
            double r = 1.5 + RANDOM.nextDouble() * 4.5;
            double sx = target.getX() + Math.cos(ang) * r;
            double sz = target.getZ() + Math.sin(ang) * r;
            double sy = groundYAt(level, sx, target.getY(), sz);
            b.mind.mines.add(new MindMine(sx, sy, sz, fuse, 2.2F, dmg, false));
         }
      }
   }

   private static void mindMine(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 34.0);
      if (target != null) {
         mindCastFx(level, witch);
         long fuse = now + (b.mind.phase2 ? 22 : 32);
         float dmg = b.mind.phase2 ? 12.0F : 10.0F;
         double sy = groundYAt(level, target.getX(), target.getY(), target.getZ());
         b.mind.mines.add(new MindMine(target.getX(), sy, target.getZ(), fuse, 3.6F, dmg, true));
         if (b.mind.phase2) {
            ServerPlayer other = null;
            double bd = 900.0;

            for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator() && !pl.getUUID().equals(target.getUUID()))) {
               double d = p.distanceToSqr(witch);
               if (d < bd) {
                  bd = d;
                  other = p;
               }
            }

            if (other != null) {
               double oy = groundYAt(level, other.getX(), other.getY(), other.getZ());
               b.mind.mines.add(new MindMine(other.getX(), oy, other.getZ(), fuse + 8L, 3.6F, dmg, true));
            }
         }
      }
   }

   private static void tickMindMines(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      Iterator<MindMine> it = m.mines.iterator();

      while (it.hasNext()) {
         MindMine mine = it.next();
         if (now >= mine.fuse) {
            it.remove();
            if (mine.voidMine) {
               level.playSound(null, mine.x, mine.y, mine.z, SoundEvents.WARDEN_SONIC_BOOM, SoundSource.HOSTILE, 1.2F, 0.7F);
            } else {
               level.playSound(null, mine.x, mine.y, mine.z, SoundEvents.GENERIC_EXPLODE, SoundSource.HOSTILE, 0.9F, 0.6F);
            }

            if (mine.voidMine) {
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, mine.x, mine.y + 0.4, mine.z, 40, mine.radius * 0.5, 0.5, mine.radius * 0.5, 0.04);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-15724504, 1.6F), mine.x, mine.y + 0.3, mine.z, 30, mine.radius * 0.5, 0.3, mine.radius * 0.5, 0.05);
            } else {
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, mine.x, mine.y + 0.5, mine.z, 26, 1.2, 1.0, 1.2, 0.05);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.3F), mine.x, mine.y + 0.4, mine.z, 22, 1.0, 0.8, 1.0, 0.05);
            }

            for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator())) {
               double dx = p.getX() - mine.x;
               double dz = p.getZ() - mine.z;
               double d = Math.sqrt(dx * dx + dz * dz);
               if (d <= mine.radius) {
                  float dealt = mine.dmg * (1.0F - 0.4F * (float)(d / mine.radius));
                  p.hurtServer(level, level.damageSources().mobAttack(witch), dealt);
                  if (mine.voidMine) {
                     double pull = (mine.radius - d) / mine.radius;
                     p.setDeltaMovement(-dx / d * pull * 1.4, 0.3, -dz / d * pull * 1.4);
                     p.hurtMarked = true;
                  }
               }
            }
         } else if (mine.voidMine) {
            if (now % 3L == 0L) {
               for (int i = 0; i < 6; i++) {
                  double a = i / 6.0 * Math.PI * 2.0 + now * 0.06;
                  com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.LARGE_SMOKE,
                     mine.x + Math.cos(a) * mine.radius * 0.45,
                     mine.y + 0.2,
                     mine.z + Math.sin(a) * mine.radius * 0.45,
                     1,
                     0.1,
                     0.1,
                     0.1,
                     0.0
                  );
               }

               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-14671808, 1.0F), mine.x, mine.y + 0.1, mine.z, 5, mine.radius * 0.4, 0.05, mine.radius * 0.4, 0.0);
            }
         } else if (now % 5L == 0L) {
            for (int i = 0; i < 12; i++) {
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, mine.x, mine.y + i * 0.5, mine.z, 1, 0.1, 0.05, 0.1, 0.0);
            }
         }
      }
   }

   private static void mindQuake(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      m.quakeUntil = now + (m.phase2 ? 75 : 45);
      m.quakeR = 1.5;
      m.quakeHits.clear();
      m.quake2At = m.phase2 ? now + 32L : 0L;
      mindCastFx(level, witch);
      com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.EXPLOSION, witch.getX(), witch.getY() + 0.5, witch.getZ(), 10, 1.5, 0.4, 1.5, 0.05);
   }

   private static void tickMindQuake(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      double r = m.quakeR;
      if (now >= m.quake2At && m.quake2At > 0L) {
         m.quakeR = 1.5;
         m.quake2At = 0L;
         m.quakeHits.clear();
      }

      if (now % 2L == 0L) {
         int count = Math.max(14, (int)(r * Math.PI * 2.0 / 1.1));

         for (int i = 0; i < count; i++) {
            double a = (double)i / count * Math.PI * 2.0;
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.0F),
               witch.getX() + Math.cos(a) * r,
               witch.getY() + 0.4,
               witch.getZ() + Math.sin(a) * r,
               1,
               0.05,
               0.05,
               0.05,
               0.0
            );
         }
      }

      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator())) {
         double d = Math.sqrt(p.distanceToSqr(witch.getX(), p.getY(), witch.getZ()));
         if (Math.abs(d - r) < 1.1 && !m.quakeHits.contains(p.getUUID()) && p.onGround()) {
            m.quakeHits.add(p.getUUID());
            p.hurtServer(level, level.damageSources().mobAttack(witch), m.phase2 ? 10.0F : 9.0F);
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.CRIT, p.getX(), p.getY() + 1.0, p.getZ(), 18, 0.6, 0.6, 0.6, 0.12);
         }
      }

      m.quakeR += 0.62;
      if (m.quakeR > 24.0) {
         m.quakeUntil = 0L;
      }
   }

   private static void mindCorruptionWave(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      m.waveUntil = now + 55L;
      m.waveR = 2.0;
      m.waveHits.clear();
      mindCastFx(level, witch);
      com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-8371969, 1.4F), witch.getX(), witch.getY() + 0.5, witch.getZ(), 20, 2.0, 0.5, 2.0, 0.05);
   }

   private static void tickMindWave(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      double r = m.waveR;
      if (now % 2L == 0L) {
         int count = Math.max(14, (int)(r * Math.PI * 2.0 / 1.2));

         for (int i = 0; i < count; i++) {
            double a = (double)i / count * Math.PI * 2.0;
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, witch.getX() + Math.cos(a) * r, witch.getY() + 0.6, witch.getZ() + Math.sin(a) * r, 1, 0.05, 0.05, 0.05, 0.0
            );
         }
      }

      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator())) {
         double d = Math.sqrt(p.distanceToSqr(witch.getX(), p.getY(), witch.getZ()));
         if (Math.abs(d - r) < 1.3 && !m.waveHits.contains(p.getUUID())) {
            m.waveHits.add(p.getUUID());
            if (!wearsPossessedMask(p)) {
               corrupt(b, level, p);
            }

            actionBar(p, "§5The wave brushes your mind...");
         }
      }

      m.waveR += 0.85;
      if (m.waveR > 30.0) {
         m.waveUntil = 0L;
      }
   }

   private static void mindMaelstrom(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      m.maelstromUntil = now + 50L;
      mindCastFx(level, witch);
   }

   private static void tickMindMaelstrom(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      if (now % 3L == 0L) {
         for (int ring = 0; ring < 2; ring++) {
            double rad = ring == 0 ? 3.2 : 5.2;

            for (int i = 0; i < 8; i++) {
               double a = i / 8.0 * Math.PI * 2.0 + now * 0.09 + ring * Math.PI;
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL_FIRE_FLAME,
                  witch.getX() + Math.cos(a) * rad,
                  witch.getY() + 0.8,
                  witch.getZ() + Math.sin(a) * rad,
                  1,
                  0.08,
                  0.3,
                  0.08,
                  0.0
               );
            }
         }
      }

      for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator())) {
         double dx = witch.getX() - p.getX();
         double dz = witch.getZ() - p.getZ();
         double d = Math.sqrt(dx * dx + dz * dz);
         if (d < 6.5) {
            p.setDeltaMovement(p.getDeltaMovement().add(dx / d * 0.16, 0.0, dz / d * 0.16));
            p.hurtMarked = true;
            if (now % 15L == 0L) {
               p.hurtServer(level, level.damageSources().mobAttack(witch), 4.0F);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.2F), p.getX(), p.getY() + 1.0, p.getZ(), 10, 0.5, 0.6, 0.5, 0.04);
            }
         }
      }
   }

   private static void mindUltimate(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      m.ultimateUntil = now + 90L;
      m.ultimateR = 2.0;
      level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WARDEN_SONIC_BOOM, SoundSource.HOSTILE, 1.1F, 0.4F);
   }

   private static void tickMindUltimate(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      MindState m = b.mind;
      if (now >= m.ultimateUntil) {
         m.ultimateUntil = 0L;
         m.ultimateR = 0.0;
         double radius = 18.0;
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.EXPLOSION, witch.getX(), witch.getY() + 0.5, witch.getZ(), 12, radius, 0.5, radius, 0.1);
         com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.6F), witch.getX(), witch.getY() + 0.6, witch.getZ(), 60, radius, 0.6, radius, 0.08);
         com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, witch.getX(), witch.getY() + 1.0, witch.getZ(), 40, radius * 0.7, 1.0, radius * 0.7, 0.06);
         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.GENERIC_EXPLODE, SoundSource.HOSTILE, 1.4F, 0.5F);
         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), ModSounds.BOSS_SLAM, SoundSource.HOSTILE, 1.2F, 0.6F);

         for (ServerPlayer p : level.getPlayers(pl -> pl.isAlive() && !pl.isSpectator() && pl.distanceToSqr(witch) <= radius * radius)) {
            p.hurtServer(level, level.damageSources().magic(), 14.0F);
            launchBackSoft(level, witch, p);
            corrupt(b, level, p);
         }

         m.nextSpell = now + 140L;
      } else {
         m.ultimateR = m.ultimateR + (16.0 - m.ultimateR) * 0.06;
         if (now % 2L == 0L) {
            int count = Math.max(24, (int)(m.ultimateR * Math.PI * 2.0 / 1.0));

            for (int i = 0; i < count; i++) {
               double a = (double)i / count * Math.PI * 2.0 + now * 0.05;
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.2F),
                  witch.getX() + Math.cos(a) * m.ultimateR,
                  witch.getY() + 0.4,
                  witch.getZ() + Math.sin(a) * m.ultimateR,
                  1,
                  0.05,
                  0.05,
                  0.05,
                  0.0
               );
            }

            for (int i = 0; i < 6; i++) {
               double a = i / 6.0 * Math.PI * 2.0;
               double r = m.ultimateR * 0.9;
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, witch.getX() + Math.cos(a) * r, witch.getY() + 1.0, witch.getZ() + Math.sin(a) * r, 1, 0.1, 0.2, 0.1, 0.02
               );
            }
         }

         if (now % 40L == 0L) {
            level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WARDEN_SONIC_BOOM, SoundSource.HOSTILE, 0.8F, 0.6F);
         }

         witch.setDeltaMovement(0.0, witch.getDeltaMovement().y, 0.0);
      }
   }

   private static double groundYAt(ServerLevel level, double x, double fromY, double z) {
      int sx = Mth.floor(x + 0.5);
      int sz = Mth.floor(z + 0.5);
      int sy = Mth.floor(fromY);

      for (int dy = 0; dy < 16; dy++) {
         BlockPos pos = new BlockPos(sx, sy - dy, sz);
         if (!level.getBlockState(pos).isAir()) {
            return pos.getY() + 1.0;
         }
      }

      return fromY;
   }

   private static void startMindStare(ServerLevel level, Mob witch, ActiveBoss b, long now) {
      ServerPlayer target = nearestPlayerIn(level, witch, 30.0);
      if (target != null) {
         b.mind.stareVictim = target.getUUID();
         b.mind.stareUntil = now + 110L;
         b.mind.stareAccum.clear();
         mindCastFx(level, witch);
         ItemDisplay eye = (ItemDisplay)EntityTypes.ITEM_DISPLAY.create(level, EntitySpawnReason.COMMAND);
         if (eye != null) {
            eye.setItemStack(new ItemStack(Items.ENDER_EYE));
            eye.setItemTransform(ItemDisplayContext.GROUND);
            eye.setNoGravity(true);
            eye.setInvulnerable(true);
            Vec3 look = target.getLookAngle();
            eye.setPos(target.getX() + look.x * 2.2, target.getEyeY() - 0.1, target.getZ() + look.z * 2.2);
            eye.setTransformation(new Transformation(new Vector3f(), new Quaternionf(), new Vector3f(2.0F), new Quaternionf()));
            level.addFreshEntity(eye);
            b.mind.stareEye = eye.getUUID();
         }

         level.playSound(null, witch.getX(), witch.getY(), witch.getZ(), SoundEvents.WITCH_AMBIENT, SoundSource.HOSTILE, 1.0F, 0.9F);

         for (int i = 0; i < 14; i++) {
            double a = i / 14.0 * Math.PI * 2.0;
            com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(16724016, 1.0F),
               witch.getX() + Math.cos(a) * 0.5,
               witch.getY() + 1.8,
               witch.getZ() + Math.sin(a) * 0.5,
               1,
               0.05,
               0.1,
               0.05,
               0.0
            );
         }
      }
   }

   private static void spawnMindClones(MinecraftServer server, ServerLevel level, Mob witch, ActiveBoss b, long now) {
      for (UUID uid : new ArrayList<>(b.mind.clones)) {
         Entity c = findEntity(server, uid);
         if (c != null && c.isAlive()) {
            c.remove(RemovalReason.DISCARDED);
         }
      }

      b.mind.clones.clear();
      int count = b.mind.phase2 ? 3 : 2;

      for (int i = 0; i < count; i++) {
         Witch clone = (Witch)EntityTypes.WITCH.create(level, EntitySpawnReason.COMMAND);
         if (clone != null) {
            AttributeInstance hp = clone.getAttribute(Attributes.MAX_HEALTH);
            if (hp != null) {
               hp.setBaseValue(30.0);
            }

            clone.setHealth(30.0F);
            clone.setCustomName(Component.literal("§5Mind Mirror"));
            clone.setCustomNameVisible(true);
            clone.setNoAi(true);
            clone.setNoGravity(true);
            CustomData cd = (CustomData)clone.get(DataComponents.CUSTOM_DATA);
            CompoundTag tag = cd != null ? cd.copyTag() : new CompoundTag();
            tag.putBoolean("ff_mind_clone", true);
            clone.setComponent(DataComponents.CUSTOM_DATA, CustomData.of(tag));
            double a = (double)i / count * Math.PI * 2.0 + RANDOM.nextDouble();
            clone.setPos(witch.getX() + Math.cos(a) * 3.5, witch.getY() + 0.6, witch.getZ() + Math.sin(a) * 3.5);
            level.addFreshEntity(clone);
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL_FIRE_FLAME, clone.getX(), clone.getY() + 1.0, clone.getZ(), 18, 0.5, 0.6, 0.5, 0.04);
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SMOKE, clone.getX(), clone.getY() + 0.5, clone.getZ(), 10, 0.5, 0.5, 0.5, 0.02);
            b.mind.clones.add(clone.getUUID());
         }
      }

      for (ServerPlayer pl : level.getPlayers(plx -> plx.isAlive() && !plx.isSpectator())) {
         if (pl.distanceToSqr(witch) < 324.0) {
            pl.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 20, 0, false, false));
         }
      }

      b.mind.nextCloneShift = now + 70L;
   }

   public static boolean onMindDamage(LivingEntity victim, DamageSource source, float amount) {
      try {
         for (ActiveBoss b : bosses.values()) {
            if (b.mind != null && b.mind.clones.contains(victim.getUUID())) {
               ServerLevel level = (ServerLevel)victim.level();
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.EXPLOSION, victim.getX(), victim.getY() + 1.0, victim.getZ(), 8, 0.8, 0.8, 0.8, 0.1);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.SOUL, victim.getX(), victim.getY() + 1.0, victim.getZ(), 30, 0.8, 0.8, 0.8, 0.05);
               com.fortuneandfavors.net.FfVfx.particles(level, new DustParticleOptions(-4177665, 1.4F), victim.getX(), victim.getY() + 1.0, victim.getZ(), 20, 0.7, 0.7, 0.7, 0.06);
               com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.END_ROD, victim.getX(), victim.getY() + 1.0, victim.getZ(), 16, 0.6, 0.6, 0.6, 0.08);
               level.playSound(null, victim.getX(), victim.getY(), victim.getZ(), SoundEvents.GENERIC_EXPLODE, SoundSource.HOSTILE, 1.1F, 0.6F);
               if (source.getEntity() instanceof LivingEntity attacker) {
                  attacker.hurtServer(level, level.damageSources().magic(), 5.0F);
                  if (attacker instanceof ServerPlayer ap) {
                     actionBar(ap, "§cWrong one - that was just a shadow of me!");
                  }
               }

               b.mind.clones.remove(victim.getUUID());
               victim.remove(RemovalReason.KILLED);
               return false;
            }
         }
      } catch (Exception var8) {
      }

      return true;
   }

