   private static String rollFriendlyRole(boolean ascended, ServerPlayer owner) {
      if (!ascended) {
         int roll = RANDOM.nextInt(100);
         if (roll < 20) {
            return "healer";
         } else if (roll < 40) {
            return "ranged";
         } else {
            return roll < 60 ? "fighter" : "";
         }
      } else {
         for (int attempt = 0; attempt < 10; attempt++) {
            int roll = RANDOM.nextInt(100);
            String role = roll < 8 ? "evoker" : (roll < 30 ? "witch" : (roll < 56 ? "tank" : (roll < 72 ? "healer" : (roll < 88 ? "ranged" : "fighter"))));
            if (!"evoker".equals(role) || !hasLiveFriendlyRole(owner, "evoker")) {
               return role;
            }
         }

         return "witch";
      }
   }

   private static boolean hasLiveFriendlyRole(ServerPlayer owner, String role) {
      UUID ownerId = owner.getUUID();

      for (UUID id : new ArrayList<>(friendly)) {
         if (findEntity(owner.level().getServer(), id) instanceof Mob m && m.isAlive() && role.equals(friendlyRole(m)) && ownerId.equals(friendlyOwner(m))) {
            return true;
         }
      }

      return false;
   }

   private static boolean isLastFriendlyAlive(MinecraftServer server, UUID ownerId, UUID selfId) {
      if (ownerId != null && server != null) {
         for (UUID id : new ArrayList<>(friendly)) {
            if (!id.equals(selfId) && findEntity(server, id) instanceof Mob m && m.isAlive() && ownerId.equals(friendlyOwner(m))) {
               return false;
            }
         }

         return true;
      } else {
         return false;
      }
   }

   public static boolean isFriendlySkeleton(LivingEntity entity) {
      if (entity == null) {
         return false;
      }

      try {
         CustomData data = (CustomData)entity.get(DataComponents.CUSTOM_DATA);
         if (data == null) {
            return false;
         }

         CompoundTag tag = data.copyTag();
         return tag.contains("ff_friendly_owner") || tag.contains("ff_mind_dom");
      } catch (Exception e) {
         return false;
      }
   }

   private static String friendlyRole(LivingEntity entity) {
      try {
         CustomData data = (CustomData)entity.get(DataComponents.CUSTOM_DATA);
         return data == null ? "" : data.copyTag().getString("ff_friendly_role").orElse("");
      } catch (Exception e) {
         return "";
      }
   }

   private static void tickHealer(Mob mob, MinecraftServer server) {
      try {
         if (!"healer".equals(friendlyRole(mob))) {
            return;
         }

         long now = ServerClock.clock(mob.level());
         if (now % 40L == 0L) {
            ServerLevel sl = (ServerLevel)mob.level();
            UUID ownerId0 = friendlyOwner(mob);
            List<LivingEntity> aura = new ArrayList<>();
            if (ownerId0 != null) {
               ServerPlayer owner0 = server.getPlayerList().getPlayer(ownerId0);
               if (owner0 != null && owner0.isAlive() && owner0.distanceToSqr(mob) < 36.0) {
                  aura.add(owner0);
               }
            }

            for (UUID id : new ArrayList<>(friendly)) {
               if (!id.equals(mob.getUUID()) && findEntity(server, id) instanceof Mob m && m.isAlive() && m.distanceToSqr(mob) < 36.0) {
                  aura.add(m);
               }
            }

            for (LivingEntity a : aura) {
               a.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 60, 0, false, true));
            }

            if (!aura.isEmpty() && now % 80L == 0L) {
               com.fortuneandfavors.net.FfVfx.particles(sl, SpellParticleOption.create(ParticleTypes.INSTANT_EFFECT, 0.5F, 1.0F, 0.5F, 0.4F),
                  mob.getX(),
                  mob.getY() + 1.0,
                  mob.getZ(),
                  6,
                  0.9,
                  0.5,
                  0.9,
                  0.0
               );
            }
         }

         if (now % 30L != 0L) {
            return;
         }

         ServerLevel level = (ServerLevel)mob.level();
         UUID ownerId = friendlyOwner(mob);
         boolean healed = false;
         if (ownerId != null) {
            ServerPlayer owner = server.getPlayerList().getPlayer(ownerId);
            if (owner != null && owner.isAlive() && owner.distanceToSqr(mob) < 324.0 && owner.getHealth() < owner.getMaxHealth()) {
               owner.heal(5.0F);
               healed = true;
            }
         }

         for (UUID id : new ArrayList<>(friendly)) {
            if (!id.equals(mob.getUUID())
               && findEntity(server, id) instanceof Mob ally
               && ally.isAlive()
               && ally.distanceToSqr(mob) < 324.0
               && ally.getHealth() < ally.getMaxHealth()) {
               ally.heal(5.0F);
               healed = true;
            }
         }

         if (healed) {
            com.fortuneandfavors.net.FfVfx.particles(level, ParticleTypes.HEART, mob.getX(), mob.getY() + 1.2, mob.getZ(), 8, 1.4, 0.6, 1.4, 0.0);
            com.fortuneandfavors.net.FfVfx.particles(level, SpellParticleOption.create(ParticleTypes.INSTANT_EFFECT, 0.5F, 1.0F, 0.5F, 0.6F),
               mob.getX(),
               mob.getY() + 1.0,
               mob.getZ(),
               10,
               0.8,
               0.5,
               0.8,
               0.0
            );
         }
      } catch (Exception var11) {
      }
   }

   public static UUID friendlyOwner(LivingEntity entity) {
      try {
         CustomData data = (CustomData)entity.get(DataComponents.CUSTOM_DATA);
         if (data == null) {
            return null;
         }

         CompoundTag tag = data.copyTag();
         String s = tag.getString("ff_friendly_owner").orElse("");
         if (s.isEmpty()) {
            s = tag.getString("ff_mind_dom").orElse("");
         }

         return s.isEmpty() ? null : UUID.fromString(s);
      } catch (Exception e) {
         return null;
      }
   }

