   private static Vec3 formationSpot(Mob mob, ServerPlayer owner) {
      int slot = friendlySlot.getOrDefault(mob.getUUID(), 0);
      String role = friendlyRole(mob);

      double radius = switch (role) {
         case "healer" -> 1.8;
         case "ranged" -> 3.6;
         case "witch", "evoker" -> 2.6;
         default -> 2.2;
      };
      int tier = slot / 2;
      int side = slot % 2 == 0 ? 1 : -1;
      radius += tier * 0.7;
      double localAng = Math.toRadians(side * (12.0 + tier * 22.0));
      float yaw = owner.getYRot();
      double fx = -Math.sin(Math.toRadians(yaw));
      double fz = Math.cos(Math.toRadians(yaw));
      double bx = -fx;
      double bz = -fz;
      double ox = bx * Math.cos(localAng) - bz * Math.sin(localAng);
      double oz = bx * Math.sin(localAng) + bz * Math.cos(localAng);
      return new Vec3(owner.getX() + ox * radius, owner.getY(), owner.getZ() + oz * radius);
   }

   private static void wanderNearSlot(Mob mob, ServerPlayer owner) {
      try {
         ServerLevel level = (ServerLevel)mob.level();
         long now = ServerClock.clock(level);
         double[] w = friendlyWander.get(mob.getUUID());
         long end = friendlyWanderEnd.getOrDefault(mob.getUUID(), 0L);
         if (w == null || now >= end) {
            int attempt = 0;

            while (true) {
               if (attempt < 6) {
                  Vec3 spot = formationSpot(mob, owner);
                  double ang = RANDOM.nextDouble() * Math.PI * 2.0;
                  double rad = 1.2 + RANDOM.nextDouble() * 3.0;
                  double tx = spot.x + Math.cos(ang) * rad;
                  double tz = spot.z + Math.sin(ang) * rad;
                  if (!isClearSpot(level, new BlockPos((int)Math.floor(tx), (int)mob.getY(), (int)Math.floor(tz)))) {
                     attempt++;
                     continue;
                  }

                  w = new double[]{tx, tz};
               }

               if (w == null) {
                  w = new double[]{owner.getX(), owner.getZ()};
               }

               friendlyWander.put(mob.getUUID(), w);
               friendlyWanderEnd.put(mob.getUUID(), now + 60L + RANDOM.nextInt(60));
               break;
            }
         }

         double dx = w[0] - mob.getX();
         double dz = w[1] - mob.getZ();
         double d = Math.sqrt(dx * dx + dz * dz);
         if (d > 0.8) {
            double speed = 0.1 + RANDOM.nextDouble() * 0.04;
            mob.setDeltaMovement(dx / d * speed, mob.getDeltaMovement().y, dz / d * speed);
            mob.hurtMarked = true;
         } else {
            mob.setDeltaMovement(0.0, mob.getDeltaMovement().y, 0.0);
            friendlyWanderEnd.put(mob.getUUID(), Math.min(now + 40L, end));
         }

         double fdx = owner.getX() - mob.getX();
         double fdz = owner.getZ() - mob.getZ();
         float lookYaw = (float)Math.toDegrees(Math.atan2(fdz, fdx)) - 90.0F;
         mob.setYRot(lookYaw);
         mob.setYHeadRot(lookYaw);
         idleAnimation(mob);
      } catch (Exception var19) {
      }
   }

   private static void walkToward(Mob mob, double tx, double tz, double stop, double speed) {
      double dx = tx - mob.getX();
      double dz = tz - mob.getZ();
      double d = Math.sqrt(dx * dx + dz * dz);
      if (d > stop) {
         mob.setDeltaMovement(dx / d * speed, mob.getDeltaMovement().y, dz / d * speed);
         mob.hurtMarked = true;
      } else {
         mob.setDeltaMovement(0.0, mob.getDeltaMovement().y, 0.0);
      }
   }

