   private static boolean isBehindTank(Mob tank, LivingEntity ally, double fx, double fz) {
      double rx = ally.getX() - tank.getX();
      double rz = ally.getZ() - tank.getZ();
      double len = Math.sqrt(rx * rx + rz * rz);
      return len < 0.01 ? true : (rx * -fx + rz * -fz) / len > 0.1;
   }

